Translate("ptBR", "medivh", {
	title = "Medivh",
	subtitle = "O Último Guardião de Tirisfal",
	allegiance = "Ordem de Tirisfal · Karazhan",
	sections = {
		{
			title = "Resumo",
			text = [=[Medivh foi o último Guardião de {link:tirisfal-glades}Tirisfal{/link}, o campeão secreto a quem os magos mais sábios do mundo deram poder para enfrentar a {link:burning-legion}Legião Ardente{/link}. Era filho da Guardiã {link:aegwynn}Aegwynn{/link} e de Nielas Aran, conjurador da corte de {link:stormwind-city}Ventobravo{/link}. Era também o amigo mais querido do Rei {link:llane-wrynn}Llane Wrynn{/link} e de Sir {link:anduin-lothar}Anduin Lothar{/link}. Mas o poder que deveria guardar {link:azeroth}Azeroth{/link} foi envenenado antes que ele desse o primeiro suspiro, e foi Medivh quem abriu o caminho para a vinda dos orcs.]=],
		},
		{
			title = "Importância",
			text = [=[Nenhum mortal fez mais para trazer a era da guerra. Por meio de Medivh, o senhor demoníaco {link:sargeras}Sargeras{/link} alcançou o mundo e lançou a {link:horde}Horda{/link} contra os reinos {link:humans}humanos{/link}. A {link:first-war}Primeira Guerra{/link}, a queda de {link:stormwind-city}Ventobravo{/link} e cada guerra que se seguiu têm raízes na torre onde ele viveu.]=],
		},
		{
			title = "Um Nascimento Envenenado",
			text = [=[{link:aegwynn}Aegwynn{/link} queria que o filho fosse seu herdeiro, livre do conselho que tentara governá-la. Não sabia que {link:sargeras}Sargeras{/link} escondera seu espírito dentro dela desde o dia em que ela derrubara seu avatar. Quando Medivh foi concebido, o senhor demoníaco passou para a criança ainda não nascida. O menino cresceu inteligente e gentil, e percorria as matas do reino com {link:llane-wrynn}Llane{/link} e {link:anduin-lothar}Lothar{/link}. Aos catorze anos, o poder do Guardião despertou dentro dele, e com ele a escuridão que jazia por baixo. Medivh caiu num sono que nenhum curandeiro conseguiu quebrar. Por anos, ficou aos cuidados dos clérigos da {link:northshire-abbey}Abadia de Vila Norte{/link}. Quando despertou, era um homem feito, e nada disse do que vira na escuridão.]=],
		},
		{
			title = "Karazhan",
			text = [=[Medivh fez seu lar em {link:karazhan}Karazhan{/link}, uma torre solitária na terra hoje chamada {link:deadwind-pass}Trilha do Vento Morto{/link}. Ali, guiado pela vontade que vivia dentro dele, estendeu a mão através do vazio até um mundo moribundo chamado {red:draenor}Draenor{/red}. Encontrou o bruxo {link:orcs}orc{/link} {link:gul-dan}Gul'dan{/link}, e juntos abriram o {link:dark-portal}Portal Negro{/link}. O {link:kirin-tor}Kirin Tor{/link} de {link:dalaran}Dalaran{/link} enviou-lhe um jovem aprendiz, {link:khadgar}Khadgar{/link}, que passou a temer o que via na torre. A meio-orc {link:garona}Garona{/link} também veio a Karazhan como enviada da {link:horde}Horda{/link}. Por meio de Khadgar e Garona, a verdade enfim chegou a {link:stormwind-city}Ventobravo{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Na juventude, ergueu seu poder contra os trolls do sul, ao lado de {link:llane-wrynn}Llane{/link} e {link:anduin-lothar}Lothar{/link}.
• Abriu o {link:dark-portal}Portal Negro{/link} com {link:gul-dan}Gul'dan{/link} e os bruxos de Draenor.
• Tomou {link:khadgar}Khadgar{/link} como aprendiz e deixou-o aprender mais do que pretendia revelar.
• Assistiu de sua torre enquanto a {link:horde}Horda{/link} incendiava o reino de seus amigos mais antigos.]=],
		},
		{
			title = "Destino",
			text = [=[{link:anduin-lothar}Anduin Lothar{/link} e {link:khadgar}Khadgar{/link} subiram {link:karazhan}Karazhan{/link} para acabar com a guerra em sua raiz. Com a ajuda de {link:garona}Garona{/link}, enfrentaram o Guardião, e ali Medivh foi morto. No momento de sua morte, {link:gul-dan}Gul'dan{/link} tentou arrancar os segredos da Tumba de {link:sargeras}Sargeras{/link} de sua mente moribunda, e foi lançado num longo torpor como castigo. Medivh está morto. Sua torre permanece vazia e silenciosa acima da {link:deadwind-pass}Trilha do Vento Morto{/link}, e o povo da {link:duskwood}Floresta do Crepúsculo{/link} diz que luzes estranhas ainda ardem em suas janelas.]=],
		},
		{
			title = "Não Registrado",
			text = [=[O que Medivh sabia, o que escolheu e o que {link:sargeras}Sargeras{/link} escolheu por ele já não se pode distinguir. As crônicas deixam essa pergunta em aberto.]=],
		},
	},
	bonds = {
		{ id = "aegwynn", name = "Aegwynn", note = "sua mãe" },
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "seu amigo de infância" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "amigo, e seu matador" },
		{ id = "gul-dan", name = "Gul'dan", note = "abriu com ele o Portal Negro" },
		{ id = "khadgar", name = "Khadgar", note = "seu aprendiz" },
	},
})

Translate("ptBR", "aegwynn", {
	title = "Aegwynn",
	subtitle = "Guardiã de Tirisfal",
	allegiance = "Ordem de Tirisfal",
	sections = {
		{
			title = "Resumo",
			text = [=[Aegwynn foi a Guardiã de {link:tirisfal-glades}Tirisfal{/link} por mais tempo do que a maioria dos reinos existiu. O conselho secreto de Tirisfal, formado pelos maiores magos das terras {link:humans}humanas{/link} e {link:high-elves}élficas{/link}, escolheu-a como sua campeã contra a {link:burning-legion}Legião Ardente{/link} e deu-lhe poder e uma vida de muitos séculos. Ela é lembrada como a mais poderosa de todos os Guardiões, e como aquela que mais causou mal sem jamais o desejar.]=],
		},
		{
			title = "Importância",
			text = [=[Numa única vitória, Aegwynn desferiu o golpe mais pesado que a Legião já sofreu em {link:azeroth}Azeroth{/link}. No mesmo instante, abriu a porta para seu maior triunfo. O senhor demoníaco {link:sargeras}Sargeras{/link} escondeu-se dentro dela e, por meio dela, passou para seu filho, {link:medivh}Medivh{/link}.]=],
		},
		{
			title = "A Guardiã",
			text = [=[Aegwynn era orgulhosa e destemida, e não aceitava ser fantoche do conselho. Caçava demônios onde quer que andassem e manteve o manto por muitas vidas humanas. Em {red:northrend}Nortúndria{/red}, encontrou demônios caçando os últimos dragões do norte e drenando sua magia. Com a ajuda dos dragões, destruiu-os. Então o próprio {link:sargeras}Sargeras{/link} apareceu diante dela numa grande tempestade. Aegwynn lutou contra seu avatar e o matou. Selou o corpo arruinado num antigo salão que afundara sob o mar na {link:great-sundering}Grande Cisão{/link}, para que nunca mais se erguesse. Acreditou que o senhor da Legião fora derrotado. Não sabia que o espírito dele deslizara para dentro dela.]=],
		},
		{
			title = "O Herdeiro da Guardiã",
			text = [=[Nos longos anos que se seguiram, Aegwynn afastou-se do conselho. Passou a acreditar que seus membros se intrometiam nos assuntos dos reis, e decidiu que eles nunca escolheriam o próximo Guardião. Tomou como consorte Nielas Aran, conjurador da corte de {link:stormwind-city}Ventobravo{/link}, e deu-lhe um filho. Pôs o poder de {link:tirisfal-glades}Tirisfal{/link} dentro da criança, para despertar quando ela chegasse à idade adulta. Depois deixou o menino com o pai e retirou-se do mundo.]=],
		},
		{
			title = "Feitos",
			text = [=[• Manteve o manto de Guardiã por muitos séculos e destruiu demônios por todos os {link:eastern-kingdoms}Reinos do Leste{/link}.
• Defendeu os dragões de Nortúndria dos caçadores da Legião.
• Matou o avatar de {link:sargeras}Sargeras{/link} e sepultou seu corpo sob o mar.
• Desafiou o conselho de {link:tirisfal-glades}Tirisfal{/link} e escolheu o próprio herdeiro.]=],
		},
		{
			title = "Destino",
			text = [=[Aegwynn sobreviveu ao filho que gerou. Quando o {link:dark-portal}Portal Negro{/link} se abriu e a {link:horde}Horda{/link} chegou, o mundo soube o quanto seu orgulho custara. {link:medivh}Medivh{/link} caiu em {link:karazhan}Karazhan{/link}, e a linhagem dos Guardiões terminou com ele. A própria Aegwynn partiu para o exílio, com o poder esgotado. Sussurra-se entre os eruditos de {link:theramore-isle}Theramore{/link} que uma velha de grande sabedoria viveu por um tempo nos ermos de {link:kalimdor}Kalimdor{/link} e aconselhou Lady {link:jaina-proudmoore}Jaina Proudmoore{/link}. Poucos sabem seu nome, e os que sabem o guardam para si.]=],
		},
		{
			title = "Não Registrado",
			text = [=[As histórias não dizem como Aegwynn foi escolhida pela primeira vez, nem por quantos anos manteve o manto ao todo. Esta entrada registra apenas o que é certo.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Medivh", note = "seu filho" },
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "a quem dizem que ela aconselhou" },
	},
})

Translate("ptBR", "llane-wrynn", {
	title = "Llane Wrynn",
	subtitle = "Rei de Ventobravo na Primeira Guerra",
	allegiance = "Reino de Ventobravo · Casa Wrynn",
	aliases = { "Llane", "Rei Llane" },
	sections = {
		{
			title = "Resumo",
			text = [=[Llane Wrynn era Rei de {link:stormwind-city}Ventobravo{/link} quando a {link:horde}Horda{/link} atravessou o {link:dark-portal}Portal Negro{/link}. Foi um soberano orgulhoso e corajoso, amigo de infância de {link:medivh}Medivh{/link} e de {link:anduin-lothar}Anduin Lothar{/link}, e pai do Rei {link:varian-wrynn}Varian Wrynn{/link}. Guiou seu povo pela longa agonia da {link:first-war}Primeira Guerra{/link} e morreu dentro de seu próprio castelo enquanto sua cidade caía.]=],
		},
		{
			title = "Importância",
			text = [=[Llane foi o último rei da antiga {link:stormwind-city}Ventobravo{/link}. Sua morte marcou o fim de um reino que se mantivera só e orgulhoso por gerações. De sua ruína nasceu a {link:alliance}Aliança{/link}, pois os sobreviventes que ele deixou levaram o aviso dos orcs para o norte, a {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Juventude",
			text = [=[Llane cresceu na companhia de dois meninos notáveis: {link:anduin-lothar}Anduin Lothar{/link}, herdeiro de uma linhagem antiga, e {link:medivh}Medivh{/link}, filho do conjurador da corte. Os três eram inseparáveis. Quando Medivh caiu em seu longo sono, Llane tornou-se homem sem ele, e alegrou-se quando o amigo despertou. Essa amizade o cegaria nos anos seguintes.]=],
		},
		{
			title = "A Primeira Guerra",
			text = [=[Quando criaturas estranhas foram vistas no Lamaçal Negro, Llane enviou {link:anduin-lothar}Lothar{/link} para descobrir o que eram. Eram orcs, e eram apenas os primeiros. Llane nomeou Lothar seu campeão e mandou mensageiros aos outros reinos humanos, mas poucos acreditaram no relato. Por anos {link:stormwind-city}Ventobravo{/link} lutou sozinha. Aldeias arderam pela {link:elwynn-forest}Floresta de Elwynn{/link}, por {link:westfall}Cerro Oeste{/link} e por {link:redridge-mountains}Cristarrubra{/link}. A {link:horde}Horda{/link} sitiou a capital e foi repelida, pois Lothar atacou sua retaguarda de surpresa. Quando {link:khadgar}Khadgar{/link} e a meio-{link:orcs}orc{/link} {link:garona}Garona{/link} avisaram o rei de que o próprio {link:medivh}Medivh{/link} trouxera os invasores, Llane não quis acreditar que o amigo pudesse traí-lo.]=],
		},
		{
			title = "Feitos",
			text = [=[• Nomeou {link:anduin-lothar}Anduin Lothar{/link} campeão do reino e confiou-lhe sua defesa.
• Enviou avisos sobre os orcs aos outros reinos humanos.
• Defendeu {link:stormwind-city}Ventobravo{/link} contra o primeiro grande cerco da {link:horde}Horda{/link}.
• Tomou {link:garona}Garona{/link} como confidente depois da queda de {link:medivh}Medivh{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Depois da morte de {link:medivh}Medivh{/link}, o {link:orcs}orc{/link} {link:orgrim-doomhammer}Orgrim Doomhammer{/link} tomou o comando da {link:horde}Horda{/link} e a lançou contra {link:stormwind-city}Ventobravo{/link} mais uma vez. As muralhas foram rompidas, mas Llane manteve o castelo. {link:garona}Garona{/link}, que se tornara sua conselheira de confiança, ainda estava presa à vontade dos bruxos da Horda. Ela matou o rei em seus aposentos. O jovem príncipe {link:varian-wrynn}Varian{/link} viu o pai morrer. Ventobravo caiu, e a Horda a arrasou. {link:anduin-lothar}Lothar{/link} reuniu os sobreviventes e os levou através do mar até {link:lordaeron}Lordaeron{/link}. O reino de Llane foi reconstruído desde então, e seu filho reinou em seu trono até seu recente desaparecimento. Seu neto, {link:anduin-wrynn}Anduin Wrynn{/link}, espera agora no castelo reconstruído, com o nome do campeão que salvou sua família.]=],
		},
		{
			title = "Não Registrado",
			text = [=[As crônicas pouco dizem da rainha de Llane ou dos anos de seu reinado antes da abertura do Portal.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Medivh", note = "seu amigo de infância" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "seu campeão" },
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "seu filho" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "liderou a Horda que tomou sua cidade" },
		{ id = "garona", name = "Garona", note = "sua conselheira, e sua assassina" },
	},
})

Translate("ptBR", "anduin-lothar", {
	title = "Anduin Lothar",
	subtitle = "O Leão de Azeroth",
	allegiance = "Reino de Ventobravo · Aliança de Lordaeron",
	aliases = { "Lothar", "Sir Anduin Lothar" },
	sections = {
		{
			title = "Resumo",
			text = [=[Sir Anduin Lothar foi o campeão de {link:stormwind-city}Ventobravo{/link} na {link:first-war}Primeira Guerra{/link} e o primeiro Comandante Supremo da {link:alliance}Aliança{/link} na {link:second-war}Segunda Guerra{/link}. Foi o último herdeiro conhecido do sangue real de {link:arathor}Arathor{/link}, o antigo império de onde nasceram os reinos humanos. Os soldados o chamavam de Leão de {link:azeroth}Azeroth{/link}. Sem ele, as nações {link:humans}humanas{/link} talvez nunca tivessem se unido.]=],
		},
		{
			title = "Importância",
			text = [=[Lothar salvou {link:stormwind-city}Ventobravo{/link} duas vezes: uma ao tirar seu povo das cinzas, e outra ao convencer os reis do norte a lutar por ela. A {link:alliance}Aliança{/link} que ele forjou ainda perdura, e o neto de seu rei leva o seu nome.]=],
		},
		{
			title = "A Primeira Guerra",
			text = [=[Lothar era amigo de infância de {link:llane-wrynn}Llane Wrynn{/link} e de {link:medivh}Medivh{/link}. Quando os orcs foram vistos pela primeira vez no Lamaçal Negro, o rei o mandou fazer o reconhecimento, e ele voltou com a notícia de uma guerra. Llane o fez campeão do reino. Lothar lutou por todo o reino durante anos. Quando a {link:horde}Horda{/link} sitiou {link:stormwind-city}Ventobravo{/link} pela primeira vez, ele levou os cavaleiros do reino pelo mar, contornando o cerco, e atacou a retaguarda, rompendo o assalto. Com o jovem mago {link:khadgar}Khadgar{/link}, subiu {link:karazhan}Karazhan{/link} e enfrentou Medivh, seu amigo mais antigo, e ali o Guardião foi morto. Mas o reino não pôde ser salvo. Quando Ventobravo caiu, Lothar levou os sobreviventes para o norte, através do mar.]=],
		},
		{
			title = "A Segunda Guerra",
			text = [=[Em {link:lordaeron}Lordaeron{/link}, Lothar apresentou-se diante do Rei {link:terenas-menethil}Terenas Menethil{/link} e dos senhores das nações do norte e avisou-os de que a {link:horde}Horda{/link} viria por eles em seguida. Eles o ouviram. Nasceu a {link:alliance}Aliança de Lordaeron{/link}, e Lothar foi nomeado seu comandante. Os altos elfos de {link:quel-thalas}Quel'Thalas{/link} juntaram-se a ela, pois tinham uma dívida antiga com o sangue de {link:arathor}Arathor{/link}, e Lothar era seu último herdeiro. Com {link:khadgar}Khadgar{/link} e o jovem paladino {link:turalyon}Turalyon{/link} como tenentes, combateu a Horda pelos reinos do norte e a empurrou de volta para o sul.]=],
		},
		{
			title = "Feitos",
			text = [=[• Fez o reconhecimento dos primeiros orcs no Lamaçal Negro e avisou seu rei.
• Rompeu o primeiro cerco de {link:stormwind-city}Ventobravo{/link} com uma carga vinda do mar.
• Matou {link:medivh}Medivh{/link} em {link:karazhan}Karazhan{/link}, com {link:khadgar}Khadgar{/link} ao seu lado.
• Levou o povo de Ventobravo ao exílio em {link:lordaeron}Lordaeron{/link}.
• Convenceu os reinos humanos a se unirem e comandou seus exércitos.]=],
		},
		{
			title = "Destino",
			text = [=[No fim da {link:second-war}Segunda Guerra{/link}, Lothar perseguiu a {link:horde}Horda{/link} até a {link:blackrock-mountain}Montanha Rocha Negra{/link}, nas {link:burning-steppes}Estepes Ardentes{/link}. Ali, na batalha ao pé da montanha, caiu pelas mãos de {link:orgrim-doomhammer}Orgrim Doomhammer{/link}. Sua morte não quebrou a {link:alliance}Aliança{/link}. {link:turalyon}Turalyon{/link} tomou sua espada, reuniu os soldados enlutados e esmagou a Horda. {link:stormwind-city}Ventobravo{/link} foi reconquistada, e mais tarde o Rei {link:varian-wrynn}Varian Wrynn{/link} deu ao filho o nome de Anduin em honra ao campeão.]=],
		},
	},
	bonds = {
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "seu rei e amigo" },
		{ id = "medivh", name = "Medivh", note = "amigo, e inimigo" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "deu-lhe o comando da Aliança" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "seu matador" },
		{ id = "turalyon", name = "Turalyon", note = "seu tenente e sucessor" },
		{ id = "anduin-wrynn", name = "Anduin Wrynn", note = "recebeu seu nome em sua honra" },
	},
})

Translate("ptBR", "tiffin-wrynn", {
	title = "Tiffin Wrynn",
	subtitle = "Rainha de Ventobravo",
	allegiance = "Reino de Ventobravo · Casa Wrynn",
	aliases = { "Tiffin", "Rainha Tiffin" },
	sections = {
		{
			title = "Resumo",
			text = [=[Tiffin Wrynn foi a rainha do Rei {link:varian-wrynn}Varian Wrynn{/link} e a mãe do Príncipe {link:anduin-wrynn}Anduin Wrynn{/link}. Sentou-se ao lado de Varian nos anos depois da {link:second-war}Segunda Guerra{/link}, quando {link:stormwind-city}Ventobravo{/link} se reerguia de suas cinzas. Não viveu para ver a cidade terminada. Morreu na revolta dos pedreiros, vítima da disputa entre os nobres da coroa e os homens que haviam reconstruído suas muralhas.]=],
		},
		{
			title = "Importância",
			text = [=[A morte de Tiffin é uma das feridas silenciosas da nova {link:stormwind-city}Ventobravo{/link}. Tirou uma mãe do herdeiro do reino e uma esposa de seu rei. Marcou também o momento em que a raiva dos pedreiros se tornou revolta aberta, da qual nasceu a {link:defias-brotherhood}Irmandade Défias{/link}.]=],
		},
		{
			title = "A Reconstrução",
			text = [=[Depois da {link:second-war}Segunda Guerra{/link}, os exilados de {link:stormwind-city}Ventobravo{/link} voltaram para casa e encontraram sua cidade em ruínas. A {link:stonemasons-guild}Guilda dos Pedreiros{/link}, liderada por {link:edwin-vancleef}Edwin VanCleef{/link}, trabalhou por anos para reerguê-la. {link:varian-wrynn}Varian{/link}, filho de {link:llane-wrynn}Llane Wrynn{/link}, assumiu o trono de seus pais. Tiffin tornou-se sua rainha e, com o tempo, deu-lhe um filho, Anduin, que recebeu o nome do campeão {link:anduin-lothar}Anduin Lothar{/link}. Por um tempo, pareceu que o reino poderia conhecer a paz novamente.]=],
		},
		{
			title = "A Revolta",
			text = [=[A {link:house-of-nobles}Casa dos Nobres{/link} prometera pagar os pedreiros por seu trabalho. Quando o trabalho terminou, os nobres se recusaram. Os pedreiros protestaram nas ruas da capital, e o protesto virou revolta. No caos, a rainha foi atingida e morta. Os pedreiros foram expulsos da cidade em desonra, e os mais amargurados entre eles fugiram para {link:westfall}Cerro Oeste{/link}. Ali adotaram a bandana vermelha, e sua irmandade ataca o reino desde então.]=],
		},
		{
			title = "Feitos",
			text = [=[• Foi rainha de {link:stormwind-city}Ventobravo{/link} nos anos depois de sua reconstrução.
• Deu a {link:varian-wrynn}Varian{/link} um filho e herdeiro, Anduin.]=],
		},
		{
			title = "Destino",
			text = [=[Tiffin está morta. Seu filho ainda é um menino e, nestes dias, espera no {link:stormwind-keep}Castelo de Ventobravo{/link} enquanto o destino do pai continua desconhecido e o Grão-senhor {link:bolvar-fordragon}Bolvar Fordragon{/link} governa como regente. Os pedreiros que um dia serviram à coroa agora travam sua própria guerra contra ela, a partir das minas e fazendas de {link:westfall}Cerro Oeste{/link}. Muitos em {link:stormwind-city}Ventobravo{/link} ainda falam da rainha com amor, e de sua morte com vergonha.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Pouco se escreveu sobre a vida de Tiffin antes de ela se tornar rainha. As crônicas registram seu casamento, seu filho e sua morte, e quase nada de suas próprias palavras ou feitos. Esta entrada não preenche esse silêncio com suposições.]=],
		},
	},
	bonds = {
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "seu marido" },
		{ id = "anduin-wrynn", name = "Anduin Wrynn", note = "seu filho" },
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "o pai de seu marido" },
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "liderou os pedreiros cuja revolta lhe tirou a vida" },
	},
})

Translate("ptBR", "terenas-menethil", {
	title = "Terenas Menethil",
	subtitle = "Rei de Lordaeron",
	allegiance = "Reino de Lordaeron · Aliança de Lordaeron",
	aliases = { "Terenas", "Rei Terenas" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Rei Terenas Menethil II governou {link:lordaeron}Lordaeron{/link}, o maior dos reinos {link:humans}humanos{/link} do norte. Foi em sua capital que a {link:alliance}Aliança{/link} foi fundada, e sob sua bandeira que a {link:horde}Horda{/link} foi derrotada na {link:second-war}Segunda Guerra{/link}. Era pai do Príncipe {link:arthas-menethil}Arthas Menethil{/link} e da Princesa Calia. Morreu pelas mãos do filho, e seu reino morreu com ele.]=],
		},
		{
			title = "Importância",
			text = [=[Terenas foi a pedra angular da {link:alliance}Aliança de Lordaeron{/link}. Acolheu os refugiados de {link:stormwind-city}Ventobravo{/link} e ouviu {link:anduin-lothar}Anduin Lothar{/link} quando outros reis não quiseram ouvir. Mas a paz que se seguiu à sua vitória se desgastou sob seu governo, e o destino final de seu reino é o mais sombrio da história da humanidade.]=],
		},
		{
			title = "A Aliança",
			text = [=[Quando {link:anduin-lothar}Lothar{/link} trouxe os exilados de {link:stormwind-city}Ventobravo{/link} para o norte, Terenas convocou os senhores das nações humanas à sua capital. {link:gilneas}Gilneas{/link}, {link:kul-tiras}Kul Tiraz{/link}, {link:stromgarde-keep}Stromgarde{/link}, {link:alterac-mountains}Alterac{/link} e {link:dalaran}Dalaran{/link} enviaram seus soberanos e enviados, e os altos elfos de {link:quel-thalas}Quel'Thalas{/link} juntaram-se depois a eles. Terenas deu a Lothar o comando dos exércitos unidos. As terras de {link:lordaeron}Lordaeron{/link} sofreram muito na guerra, mas no fim a {link:horde}Horda{/link} foi quebrada e seus orcs foram feitos prisioneiros.]=],
		},
		{
			title = "A Paz Desgastada",
			text = [=[Depois da guerra, Terenas ordenou que os orcs capturados fossem mantidos em grandes {link:internment-camps}campos de internação{/link}. Os campos eram caros, e ele cobrou impostos das outras nações para pagá-los. Cresceram as disputas sobre os campos e sobre o destino do traiçoeiro reino de {link:alterac-mountains}Alterac{/link}. Uma a uma, {link:gilneas}Gilneas{/link}, {link:stromgarde-keep}Stromgarde{/link} e {link:quel-thalas}Quel'Thalas{/link} deixaram a {link:alliance}Aliança{/link}. Quando uma estranha peste começou a se espalhar pelas terras agrícolas do norte de {link:lordaeron}Lordaeron{/link}, o rei enviou seu filho {link:arthas-menethil}Arthas{/link} e o paladino {link:uther-the-lightbringer}Uther the Lightbringer{/link} para pôr fim a ela.]=],
		},
		{
			title = "Feitos",
			text = [=[• Acolheu em seu reino os refugiados de {link:stormwind-city}Ventobravo{/link}.
• Fundou a {link:alliance}Aliança de Lordaeron{/link} e deu a {link:anduin-lothar}Anduin Lothar{/link} o seu comando.
• Ordenou a construção dos {link:internment-camps}campos de internação{/link} depois da {link:second-war}Segunda Guerra{/link}.
• Enviou {link:arthas-menethil}Arthas{/link} e {link:uther-the-lightbringer}Uther{/link} contra a peste no norte.]=],
		},
		{
			title = "Destino",
			text = [=[{link:arthas-menethil}Arthas{/link} voltou de {red:northrend}Nortúndria{/red} como herói, e o povo da capital espalhou pétalas de flores em seu caminho. O príncipe entrou na sala do trono, ajoelhou-se diante do pai e então o matou com a espada rúnica {red:frostmourne}Gélido Lamento{/red}. Com a morte do rei, o reino caiu diante do {link:scourge}Flagelo{/link}. {link:uther-the-lightbringer}Uther{/link} mais tarde levou as cinzas do rei numa urna rumo a {link:quel-thalas}Quel'Thalas{/link}, mas Arthas derrubou o paladino e jogou as cinzas fora. A capital de Terenas jaz em ruínas, e sob ela os {link:forsaken}Renegados{/link} de Lady {link:sylvanas-windrunner}Sylvanas Windrunner{/link} construíram a {link:undercity}Cidade Baixa{/link}.]=],
		},
	},
	bonds = {
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "seu filho, e seu assassino" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "comandante de sua Aliança" },
		{ id = "uther-the-lightbringer", name = "Uther the Lightbringer", note = "seu paladino leal" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "arcebispo de sua fé" },
	},
})

Translate("ptBR", "arthas-menethil", {
	title = "Arthas Menethil",
	subtitle = "O Príncipe Caído",
	allegiance = [=[Flagelo (antes Reino de Lordaeron, Cavaleiros do Punho de Prata)]=],
	aliases = { "Arthas", "Príncipe Arthas" },
	sections = {
		{
			title = "Resumo",
			text = [=[Arthas Menethil foi o príncipe herdeiro de {link:lordaeron}Lordaeron{/link}, cavaleiro do Punho de Prata e aluno de {link:uther-the-lightbringer}Uther the Lightbringer{/link}. Era valente, amado e orgulhoso. Partiu para salvar seu povo de uma peste de mortos-vivos e acabou por destruí-lo. Assassinou o pai, o Rei {link:terenas-menethil}Terenas Menethil{/link}, e conduziu o {link:scourge}Flagelo{/link} pelo norte. Hoje governa os mortos-vivos a partir do coração gelado de {red:northrend}Nortúndria{/red}.]=],
		},
		{
			title = "Importância",
			text = [=[Nenhuma queda na história da humanidade foi tão grande nem tão terrível. O nome de Arthas é amaldiçoado em cada terra que um dia conheceu a {link:alliance}Aliança{/link}, e as terras que ele devastou ainda se chamam Terras Pestilentas.]=],
		},
		{
			title = "O Príncipe",
			text = [=[Arthas era o único filho de {link:terenas-menethil}Terenas{/link}. {link:uther-the-lightbringer}Uther{/link} o treinou como paladino da {link:holy-light}Luz Sagrada{/link}, e ele foi acolhido na ordem do Punho de Prata. Quando uma peste atingiu as terras agrícolas do norte de {link:lordaeron}Lordaeron{/link}, o rei enviou Arthas e Uther para pôr fim a ela. Com {link:jaina-proudmoore}Jaina Proudmoore{/link}, de {link:dalaran}Dalaran{/link}, ao seu lado, Arthas seguiu a doença até o necromante {link:kel-thuzad}Kel'Thuzad{/link} e seu {link:cult-of-the-damned}Culto dos Malditos{/link}, e o matou. Mas a peste continuou a se espalhar. Em Stratholme, Arthas descobriu que os grãos da cidade estavam contaminados e que todos que os haviam comido se ergueriam como mortos-vivos. Ordenou que a cidade fosse expurgada. Uther e Jaina recusaram-se a participar, e Arthas realizou o {link:culling-of-stratholme}Expurgo de Stratholme{/link} sem eles.]=],
		},
		{
			title = "A Queda",
			text = [=[Arthas perseguiu o senhor do terror Mal'Ganis até Nortúndria. Ali queimou os próprios navios para que seus homens não pudessem voltar, e empunhou a amaldiçoada espada rúnica {red:frostmourne}Gélido Lamento{/red}. Com ela matou Mal'Ganis, mas a espada tomou sua alma. Voltou a {link:lordaeron}Lordaeron{/link} como servo do {red:lich-king}Lich Rei{/red}. Na sala do trono assassinou o pai, e o reino caiu. Destruiu a ordem do Punho de Prata, matou {link:uther-the-lightbringer}Uther{/link} e ergueu {link:kel-thuzad}Kel'Thuzad{/link} outra vez junto à Nascente do Sol, depois de devastar {link:quel-thalas}Quel'Thalas{/link}. Matou a general-patrulheira {link:sylvanas-windrunner}Sylvanas Windrunner{/link} e prendeu seu espírito à sua vontade.]=],
		},
		{
			title = "Feitos",
			text = [=[• Realizou o {link:culling-of-stratholme}Expurgo de Stratholme{/link}.
• Assassinou o {link:terenas-menethil}Rei Terenas{/link} e entregou {link:lordaeron}Lordaeron{/link} ao {link:scourge}Flagelo{/link}.
• Matou {link:uther-the-lightbringer}Uther the Lightbringer{/link}.
• Devastou {link:quel-thalas}Quel'Thalas{/link} e profanou a Nascente do Sol para erguer {link:kel-thuzad}Kel'Thuzad{/link} como lich.
• Abriu o caminho da {link:burning-legion}Legião Ardente{/link} até {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Depois da {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link}, o poder do Lich Rei enfraqueceu, e Arthas perdeu o domínio sobre {link:lordaeron}Lordaeron{/link}. {link:sylvanas-windrunner}Sylvanas{/link} libertou-se de seu controle, e os {link:forsaken}Renegados{/link} se levantaram contra ele. Convocado por seu mestre, Arthas voltou a Nortúndria. Na geleira da Coroa de Gelo, lutou contra {link:illidan-stormrage}Illidan Stormrage{/link} e o derrotou. Então subiu ao Trono de Gelo e pôs o elmo do Lich Rei, e os dois se tornaram um. Arthas agora reina como o Lich Rei em Nortúndria. Em Lordaeron, {link:kel-thuzad}Kel'Thuzad{/link} comanda o {link:scourge}Flagelo{/link} em seu nome. {link:muradin-bronzebeard}Muradin Bronzebeard{/link}, que um dia o seguiu para o norte, nunca voltou para casa.]=],
		},
	},
	bonds = {
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "seu pai, e sua vítima" },
		{ id = "uther-the-lightbringer", name = "Uther the Lightbringer", note = "seu mestre, e sua vítima" },
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "seu amor perdido" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "inimigo, depois servo" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "o Lich Rei a quem se uniu" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "inimigo na Coroa de Gelo" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "sua vítima e inimiga" },
	},
})

Translate("ptBR", "uther-the-lightbringer", {
	title = "Uther the Lightbringer",
	subtitle = "Primeiro dos Paladinos",
	allegiance = "Cavaleiros do Punho de Prata · Igreja da Luz Sagrada",
	aliases = { "Uther", "Lorde Uther" },
	sections = {
		{
			title = "Resumo",
			text = [=[Uther the Lightbringer foi o primeiro paladino da {link:holy-light}Luz Sagrada{/link} e o líder dos Cavaleiros do Punho de Prata. Aprendeu sua fé ao lado do Arcebispo {link:alonsus-faol}Alonsus Faol{/link}, combateu a {link:horde}Horda{/link} pelo norte na {link:second-war}Segunda Guerra{/link} e treinou o príncipe {link:arthas-menethil}Arthas Menethil{/link}. Foi mestre e amigo do príncipe, e morreu pelas mãos dele.]=],
		},
		{
			title = "Importância",
			text = [=[Uther mostrou aos reinos humanos que fé e aço podiam lutar juntos. A ordem que ele liderou defendeu {link:lordaeron}Lordaeron{/link} por uma geração, e seu nome ainda é pronunciado com reverência por todos os paladinos do mundo.]=],
		},
		{
			title = "O Punho de Prata",
			text = [=[Depois da {link:first-war}Primeira Guerra{/link}, chegou ao norte a notícia de que a {link:horde}Horda{/link} massacrara os clérigos da {link:northshire-abbey}Abadia de Vila Norte{/link}. {link:alonsus-faol}Alonsus Faol{/link} decidiu que os servos da Luz não ficariam mais indefesos. Com a bênção de {link:anduin-lothar}Anduin Lothar{/link}, reuniu guerreiros de fé forte e ensinou-os a empunhar o poder sagrado em batalha. Uther foi o primeiro entre eles. Quando o treinamento terminou, o arcebispo o nomeou líder dos novos Cavaleiros do Punho de Prata. Uther e seus paladinos, entre eles {link:turalyon}Turalyon{/link} e {link:tirion-fordring}Tirion Fordring{/link}, lutaram durante toda a {link:second-war}Segunda Guerra{/link} e levaram cura e esperança aonde a luta era mais dura.]=],
		},
		{
			title = "O Príncipe",
			text = [=[Nos anos de paz, Uther tomou o jovem {link:arthas-menethil}Arthas{/link} como aluno e o acolheu na ordem. Quando uma peste irrompeu no norte de {link:lordaeron}Lordaeron{/link}, o Rei {link:terenas-menethil}Terenas Menethil{/link} enviou os dois para pôr fim a ela. Em Stratholme, Arthas ordenou que o povo da cidade fosse morto antes que a peste o erguesse. Uther recusou-se. Não mataria os vivos, e Arthas o dispensou de seu serviço. O {link:culling-of-stratholme}Expurgo de Stratholme{/link} prosseguiu sem ele.]=],
		},
		{
			title = "Feitos",
			text = [=[• Foi o primeiro paladino ordenado por {link:alonsus-faol}Alonsus Faol{/link} e liderou os Cavaleiros do Punho de Prata.
• Combateu a {link:horde}Horda{/link} na {link:second-war}Segunda Guerra{/link}.
• Treinou o {link:arthas-menethil}Príncipe Arthas{/link} nos caminhos da Luz.
• Recusou-se a participar do {link:culling-of-stratholme}Expurgo de Stratholme{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Quando {link:arthas-menethil}Arthas{/link} voltou de {red:northrend}Nortúndria{/red} e assassinou o pai, o príncipe se voltou contra a ordem que o formara. Quebrou o Punho de Prata e caçou seus cavaleiros. Uther e seus últimos paladinos guardavam a urna com as cinzas do {link:terenas-menethil}Rei Terenas{/link}. Arthas veio buscá-la, e o aluno matou o mestre com a espada rúnica {red:frostmourne}Gélido Lamento{/red}. Uma tumba se ergue hoje em memória de Uther nas {link:western-plaguelands}Terras Pestilentas Ocidentais{/link}, um lugar de luto numa terra morta. Alguns dos paladinos que ele treinou ainda vivem, e se lembram dele.]=],
		},
	},
	bonds = {
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "seu mentor" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "seu aluno, e seu matador" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "seu rei" },
		{ id = "turalyon", name = "Turalyon", note = "um irmão do Punho de Prata" },
		{ id = "tirion-fordring", name = "Tirion Fordring", note = "um irmão do Punho de Prata" },
	},
})

Translate("ptBR", "alonsus-faol", {
	title = "Alonsus Faol",
	subtitle = "Arcebispo da Luz Sagrada",
	allegiance = "Igreja da Luz Sagrada · Cavaleiros do Punho de Prata",
	aliases = { "Arcebispo Faol", "Arcebispo Alonsus Faol" },
	sections = {
		{
			title = "Resumo",
			text = [=[Alonsus Faol foi o Arcebispo da Igreja da {link:holy-light}Luz Sagrada{/link}, o pai espiritual dos reinos humanos na era da {link:second-war}Segunda Guerra{/link}. Era um velho baixo e robusto, de barba branca e rosto bondoso, amado igualmente por plebeus e reis. Fundou os Cavaleiros do Punho de Prata e ordenou {link:uther-the-lightbringer}Uther the Lightbringer{/link} como o primeiro dos paladinos.]=],
		},
		{
			title = "Importância",
			text = [=[Antes de Faol, os servos da Luz curavam e rezavam enquanto outros lutavam. Depois dele, cavalgaram para a guerra. As ordens de paladinos de todas as terras humanas, e os jovens paladinos hoje treinados na {link:northshire-abbey}Abadia de Vila Norte{/link}, percorrem todos o caminho que ele abriu.]=],
		},
		{
			title = "O Punho de Prata",
			text = [=[Faol servia à fé havia muito tempo, e tomou o jovem {link:uther-the-lightbringer}Uther{/link} como aprendiz muitos anos antes da chegada dos orcs. Durante a {link:first-war}Primeira Guerra{/link}, a {link:horde}Horda{/link} incendiou a abadia de {link:northshire-abbey}Vila Norte{/link} e massacrou seus clérigos. Quando os sobreviventes de {link:stormwind-city}Ventobravo{/link} chegaram a {link:lordaeron}Lordaeron{/link}, o arcebispo soube do massacre e decidiu que ele não se repetiria. Junto com {link:anduin-lothar}Anduin Lothar{/link}, fundou uma ordem de guerreiros sagrados. Escolheu cavaleiros de fé forte e ensinou-os a invocar a Luz em batalha. Uther, {link:turalyon}Turalyon{/link}, {link:tirion-fordring}Tirion Fordring{/link} e alguns outros foram os primeiros. Quando o treinamento terminou, Faol nomeou Uther líder dos Cavaleiros do Punho de Prata.]=],
		},
		{
			title = "A Paz",
			text = [=[Faol estava presente quando os senhores das nações humanas se reuniram na capital de {link:lordaeron}Lordaeron{/link}. Dizem que ajudou a esfriar os ânimos quando as disputas esquentavam. Depois da guerra, voltou seus cuidados para a reconstrução do sul. Enviou seus sacerdotes e paladinos aonde eram necessários e apoiou a construção da nova {link:cathedral-of-light}Catedral da Luz{/link} em {link:stormwind-city}Ventobravo{/link} e a restauração de {link:northshire-abbey}Vila Norte{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Treinou {link:uther-the-lightbringer}Uther{/link} na fé da Luz.
• Fundou os Cavaleiros do Punho de Prata com {link:anduin-lothar}Anduin Lothar{/link}.
• Ordenou os primeiros paladinos e nomeou Uther seu líder.
• Aconselhou os senhores da {link:alliance}Aliança{/link} durante a {link:second-war}Segunda Guerra{/link}.
• Ajudou na reconstrução de {link:stormwind-city}Ventobravo{/link} e da {link:northshire-abbey}Abadia de Vila Norte{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Faol morreu nos anos depois da {link:second-war}Segunda Guerra{/link}. As crônicas não dizem como. Seu aluno {link:archbishop-benedictus}Benedictus{/link} o sucedeu como arcebispo e ainda cuida da {link:cathedral-of-light}Catedral da Luz{/link} em {link:stormwind-city}Ventobravo{/link}. Faol foi sepultado nas {link:tirisfal-glades}Clareiras de Tirisfal{/link}, numa tumba chamada Repouso de Faol. Aquela terra pertence agora aos mortos-vivos, e os {link:forsaken}Renegados{/link} andam por onde os fiéis um dia vinham rezar.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhuma crônica conta como Alonsus Faol morreu, nem quando. Tampouco registra muito de sua vida antes de ele se tornar arcebispo.]=],
		},
	},
	bonds = {
		{ id = "uther-the-lightbringer", name = "Uther the Lightbringer", note = "seu aprendiz" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "fundou com ele o Punho de Prata" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "seu rei em Lordaeron" },
	},
})

Translate("ptBR", "orgrim-doomhammer", {
	title = "Orgrim Doomhammer",
	subtitle = "Chefe Guerreiro da Horda na Segunda Guerra",
	allegiance = "Horda · clã Rocha Negra",
	aliases = { "Orgrim", "Chefe Guerreiro Doomhammer" },
	sections = {
		{
			title = "Resumo",
			text = [=[Orgrim Doomhammer foi o Chefe Guerreiro da {link:horde}Horda{/link} que conquistou {link:stormwind-city}Ventobravo{/link} e liderou os orcs na {link:second-war}Segunda Guerra{/link}. Era um guerreiro do {link:blackrock-clan}clã Rocha Negra{/link}, portador do grande martelo de sua família e o amigo mais antigo de Durotan, dos {link:frostwolf-clan}Lobo do Gelo{/link}. Odiava os bruxos que haviam corrompido seu povo e tentou, a seu modo, libertá-lo. No fim da vida encontrou o {link:orcs}orc{/link} que concluiria essa obra: {link:thrall}Thrall{/link}.]=],
		},
		{
			title = "Importância",
			text = [=[Doomhammer fez da {link:horde}Horda{/link} um único exército com uma única vontade. Sob seu comando, ela chegou mais perto do que nunca de conquistar os reinos humanos. Mas seu maior legado não é uma conquista. É a nova Horda, e sua capital, {link:orgrimmar}Orgrimmar{/link}, leva o seu nome.]=],
		},
		{
			title = "A Primeira Guerra",
			text = [=[Nos primeiros anos da guerra, Orgrim serviu como braço direito do Chefe Guerreiro Blackhand, um fantoche do bruxo {link:gul-dan}Gul'dan{/link}. Quando Durotan foi assassinado pelos matadores de Gul'dan, a raiva de Orgrim não pôde mais ser contida. Depois da morte de {link:medivh}Medivh{/link}, desafiou Blackhand para um duelo até a morte e esmagou-lhe o crânio com o Martelo da Perdição. Como Chefe Guerreiro, proibiu a magia sombria que envenenara Draenor. Lançou a {link:horde}Horda{/link} contra {link:stormwind-city}Ventobravo{/link} mais uma vez, e desta vez a cidade caiu. Depois encontrou o covil do {link:shadow-council}Conselho das Sombras{/link} dos bruxos e massacrou a maioria deles.]=],
		},
		{
			title = "A Segunda Guerra",
			text = [=[Doomhammer poupou {link:gul-dan}Gul'dan{/link}, que lhe prometeu novas armas. Convocou toda a força da {link:horde}Horda{/link} e marchou para o norte. Tomou as {link:kingdom-of-ironforge}terras dos anões{/link} de Khaz Modan, aliou-se aos trolls da floresta Amani e usou em batalha os dragões vermelhos do {link:dragonmaw-clan}clã Presa do Dragão{/link}. Seus exércitos incendiaram as florestas de {link:quel-thalas}Quel'Thalas{/link} e sitiaram a capital de {link:lordaeron}Lordaeron{/link}. Então Gul'dan o traiu e levou embora grande parte da Horda. O cerco fracassou. Na {link:blackrock-mountain}Montanha Rocha Negra{/link}, Doomhammer matou {link:anduin-lothar}Anduin Lothar{/link} em batalha, mas o paladino {link:turalyon}Turalyon{/link} reuniu a {link:alliance}Aliança{/link}, e a Horda foi esmagada.]=],
		},
		{
			title = "Feitos",
			text = [=[• Matou Blackhand e fez-se Chefe Guerreiro.
• Conquistou {link:stormwind-city}Ventobravo{/link} e encerrou a {link:first-war}Primeira Guerra{/link}.
• Destruiu o {link:shadow-council}Conselho das Sombras{/link}.
• Levou a {link:horde}Horda{/link} aos portões da capital de {link:lordaeron}Lordaeron{/link}.
• Matou {link:anduin-lothar}Anduin Lothar{/link} na {link:blackrock-mountain}Montanha Rocha Negra{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Doomhammer foi capturado e exibido acorrentado na capital de {link:lordaeron}Lordaeron{/link}. Fugiu e viveu escondido por muitos anos. Quando o jovem {link:thrall}Thrall{/link}, filho de Durotan, foi procurá-lo, o velho chefe guerreiro o reconheceu de imediato. Juntou-se a Thrall para libertar os orcs dos {link:internment-camps}campos de internação{/link}, e caiu numa dessas batalhas, nas colinas de {link:hillsbrad-foothills}Eira dos Montes{/link}. Antes de morrer, nomeou Thrall o novo Chefe Guerreiro. Thrall hoje veste a armadura negra de Doomhammer e carrega seu martelo em {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "seu herdeiro como Chefe Guerreiro" },
		{ id = "gul-dan", name = "Gul'dan", note = "o bruxo que ele desprezava" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "o inimigo que ele matou" },
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "o rei cuja cidade ele tomou" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "um companheiro chefe de clã" },
	},
})

Translate("ptBR", "grom-hellscream", {
	title = "Grom Hellscream",
	subtitle = "Chefe do Brado Guerreiro",
	allegiance = "Horda · clã Brado Guerreiro",
	aliases = { "Grommash", "Grommash Hellscream" },
	sections = {
		{
			title = "Resumo",
			text = [=[Grom Hellscream foi o chefe do clã Brado Guerreiro, o mais feroz dos senhores da guerra {link:orcs}orcs{/link} e o amigo mais verdadeiro de {link:thrall}Thrall{/link}. Foi o primeiro orc a beber o sangue do demônio {link:mannoroth}Mannoroth{/link}, e assim prendeu seu povo à {link:burning-legion}Legião Ardente{/link}. Foi também o orc que quebrou esse laço, ao custo da própria vida.]=],
		},
		{
			title = "Importância",
			text = [=[A maldição dos orcs começou com Grom e terminou com ele. Sua morte no {link:ashenvale}Vale Gris{/link} libertou os orcs do sangue demoníaco, e a {link:horde}Horda{/link} de hoje deve sua liberdade à sua última resistência.]=],
		},
		{
			title = "A Maldição do Sangue",
			text = [=[Em {red:draenor}Draenor{/red}, o bruxo {link:gul-dan}Gul'dan{/link} reuniu os chefes dos clãs e ofereceu-lhes um gole do sangue de {link:mannoroth}Mannoroth{/link}. Grom foi o primeiro a beber, e os outros o seguiram. O sangue encheu os orcs de uma fúria terrível e os prendeu à vontade da Legião. Quando a {link:horde}Horda{/link} marchou sobre {link:azeroth}Azeroth{/link}, Gul'dan tramou para manter Grom e seu Brado Guerreiro em Draenor. Eles perderam toda a {link:second-war}Segunda Guerra{/link}. Depois da guerra, atravessaram o {link:dark-portal}Portal Negro{/link} e lutaram por ele até que fosse destruído, e ficaram presos nas terras humanas.]=],
		},
		{
			title = "A Letargia",
			text = [=[Por muitos anos, o Brado Guerreiro viveu escondido nos ermos de {link:lordaeron}Lordaeron{/link}. Como todos os orcs, Grom adoeceu com a perda da fúria demoníaca. Mas combateu a letargia com vontade de ferro. Quando o jovem {link:thrall}Thrall{/link} foi procurá-lo, Grom viu nele a esperança de seu povo. Juntou-se a Thrall para libertar os orcs dos {link:internment-camps}campos de internação{/link}. Foi capturado pelos humanos às vésperas da {link:third-war}Terceira Guerra{/link}, e Thrall o libertou outra vez.]=],
		},
		{
			title = "Kalimdor",
			text = [=[Os orcs navegaram para o oeste, até {link:kalimdor}Kalimdor{/link}. Ali o Brado Guerreiro foi enviado às florestas do {link:ashenvale}Vale Gris{/link} para cortar madeira, e entrou em choque com os {link:night-elves}elfos noturnos{/link}. O semideus {link:cenarius}Cenarius{/link} veio defender a floresta. Desesperados pela vitória, Grom e seus guerreiros beberam de uma fonte que {link:mannoroth}Mannoroth{/link} conspurcara com seu sangue. A velha maldição voltou. Naquela fúria, Grom matou Cenarius. {link:thrall}Thrall{/link}, ajudado por {link:jaina-proudmoore}Jaina Proudmoore{/link}, capturou o amigo e o purificou da fúria.]=],
		},
		{
			title = "Feitos",
			text = [=[• Foi o primeiro {link:orcs}orc{/link} a beber o sangue de {link:mannoroth}Mannoroth{/link}.
• Defendeu o {link:dark-portal}Portal Negro{/link} contra a {link:alliance}Aliança{/link} depois da {link:second-war}Segunda Guerra{/link}.
• Resistiu à letargia órquica durante anos escondido.
• Ajudou {link:thrall}Thrall{/link} a libertar os orcs dos campos.
• Matou {link:cenarius}Cenarius{/link}, e depois matou Mannoroth.]=],
		},
		{
			title = "Destino",
			text = [=[Grom e {link:thrall}Thrall{/link} foram juntos ao cânion onde {link:mannoroth}Mannoroth{/link} esperava. Thrall caiu diante do poder do demônio. Grom avançou sozinho, cravou o machado no peito de Mannoroth e o matou. A morte do demônio libertou os orcs da maldição do sangue. Grom morreu dos ferimentos nos braços de Thrall. Seu clã ainda corta as árvores do {link:ashenvale}Vale Gris{/link} em nome da {link:horde}Horda{/link}, e os elfos noturnos ainda o combatem por cada árvore.]=],
		},
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "seu Chefe Guerreiro e amigo" },
		{ id = "gul-dan", name = "Gul'dan", note = "deu-lhe o sangue do demônio" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "um companheiro chefe de clã" },
		{ id = "archimonde", name = "Archimonde", note = "o senhor do demônio que ele matou" },
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "ajudou a libertá-lo" },
	},
})

Translate("ptBR", "gul-dan", {
	title = "Gul'dan",
	subtitle = "O Traidor dos Orcs",
	allegiance = "Conselho das Sombras · clã Stormreaver",
	sections = {
		{
			title = "Resumo",
			text = [=[Gul'dan foi o primeiro bruxo {link:orcs}orc{/link} e o arquiteto da antiga {link:horde}Horda{/link}. Foi outrora aprendiz do xamã {link:ner-zhul}Ner'zhul{/link}. Vendeu seu povo à {link:burning-legion}Legião Ardente{/link} em troca de poder, e envenenou tanto sua raça quanto seu mundo. Abriu o {link:dark-portal}Portal Negro{/link} com {link:medivh}Medivh{/link} e liderou os senhores ocultos da Horda, o {link:shadow-council}Conselho das Sombras{/link}. No fim, traiu a própria Horda.]=],
		},
		{
			title = "Importância",
			text = [=[Grande parte do sofrimento dos orcs, e dos povos que eles combateram, remonta à ambição de Gul'dan. Sua {link:fel-magic}magia vil{/link} drenou a vida de {red:draenor}Draenor{/red}. Seu sangue demoníaco tornou os orcs escravos de sua fúria. Sua traição custou à {link:horde}Horda{/link} a {link:second-war}Segunda Guerra{/link}.]=],
		},
		{
			title = "O Conselho das Sombras",
			text = [=[Em Draenor, o senhor demoníaco {link:kil-jaeden}Kil'jaeden{/link} procurou um servo entre os orcs. Quando {link:ner-zhul}Ner'zhul{/link} começou a duvidar do demônio, Kil'jaeden voltou-se para Gul'dan, que não tinha dúvida alguma. Kil'jaeden ensinou-lhe as artes da feitiçaria vil. Gul'dan fundou o {link:shadow-council}Conselho das Sombras{/link}, um círculo de bruxos que governava os clãs por trás de um chefe guerreiro fantoche, Blackhand. Ofereceu aos chefes o sangue de {link:mannoroth}Mannoroth{/link}, e eles beberam. Então uma voz de outro mundo o alcançou. Era {link:medivh}Medivh{/link}, e juntos abriram o {link:dark-portal}Portal Negro{/link} para {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "As Guerras",
			text = [=[No fim da {link:first-war}Primeira Guerra{/link}, Gul'dan tentou arrancar os segredos da Tumba de {link:sargeras}Sargeras{/link} da mente moribunda de {link:medivh}Medivh{/link}. O esforço o lançou num longo torpor. Enquanto ele dormia, {link:orgrim-doomhammer}Orgrim Doomhammer{/link} matou Blackhand e destruiu a maior parte do {link:shadow-council}Conselho das Sombras{/link}. Quando Gul'dan despertou, comprou a vida com a promessa de novas armas. Ele e seus bruxos ergueram os primeiros cavaleiros da morte da {link:horde}Horda{/link}. Mas sua lealdade era uma máscara. Enquanto Doomhammer sitiava a capital de {link:lordaeron}Lordaeron{/link}, Gul'dan levou seus seguidores e partiu pelo mar em busca da Tumba de Sargeras, no fundo do oceano.]=],
		},
		{
			title = "Feitos",
			text = [=[• Fundou o {link:shadow-council}Conselho das Sombras{/link} e governou a {link:horde}Horda{/link} por meio de Blackhand.
• Deu aos chefes o sangue de {link:mannoroth}Mannoroth{/link}.
• Abriu o {link:dark-portal}Portal Negro{/link} com {link:medivh}Medivh{/link}.
• Ergueu os primeiros cavaleiros da morte da Horda.
• Abandonou Doomhammer aos portões da capital de {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Gul'dan ergueu a Tumba de {link:sargeras}Sargeras{/link} das profundezas do Grande Oceano e entrou nela, esperando reivindicar o poder de um deus. Os demônios que a guardavam o despedaçaram. Os guerreiros de Doomhammer, enviados para punir sua traição, massacraram seus seguidores. Sem eles, a {link:horde}Horda{/link} não pôde manter o cerco e foi empurrada à derrota. O {link:skull-of-gul-dan}crânio de Gul'dan{/link} sobreviveu a ele e carregou um poder sombrio próprio até ser destruído na {link:third-war}Terceira Guerra{/link}.]=],
		},
	},
	bonds = {
		{ id = "ner-zhul", name = "Ner'zhul", note = "seu primeiro mestre" },
		{ id = "medivh", name = "Medivh", note = "abriu com ele o Portal Negro" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "o chefe guerreiro que ele traiu" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "o primeiro a beber o sangue que ele ofereceu" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "tomou o poder de seu crânio" },
	},
})

Translate("ptBR", "ner-zhul", {
	title = "Ner'zhul",
	subtitle = "Xamã Ancião dos Shadowmoon",
	allegiance = "clã Shadowmoon · Flagelo",
	sections = {
		{
			title = "Resumo",
			text = [=[Ner'zhul foi o xamã ancião do clã Shadowmoon e o líder espiritual mais respeitado dos orcs de {red:draenor}Draenor{/red}. O senhor demoníaco {link:kil-jaeden}Kil'jaeden{/link} o enganou e o usou para voltar os orcs contra os draenei. Mais tarde, Ner'zhul despedaçou o próprio mundo na tentativa de fugir dele. Capturado pelos demônios, foi transformado no {red:lich-king}Lich Rei{/red}, senhor do {link:scourge}Flagelo{/link}.]=],
		},
		{
			title = "Importância",
			text = [=[Ner'zhul trouxe a ruína duas vezes. Como xamã, abriu o coração de seu povo à {link:burning-legion}Legião Ardente{/link}. Como Lich Rei, lançou uma peste de mortos-vivos sobre {link:lordaeron}Lordaeron{/link}. A {link:third-war}Terceira Guerra{/link} e as terras mortas do norte são obra sua tanto quanto de qualquer outro.]=],
		},
		{
			title = "O Enganador",
			text = [=[Nos velhos tempos de Draenor, os orcs viviam em clãs de caçadores e xamãs. Ner'zhul falava pelos espíritos entre eles. Então {link:kil-jaeden}Kil'jaeden{/link} veio a ele, disfarçado de espírito dos ancestrais, e sussurrou que os pacíficos draenei tramavam contra os orcs. Ner'zhul acreditou e levou seu povo à guerra. Só mais tarde viu a verdade, e quando se recusou a ir adiante, Kil'jaeden voltou-se para seu aprendiz, {link:gul-dan}Gul'dan{/link}. Ner'zhul foi posto de lado e viveu envergonhado enquanto a {link:horde}Horda{/link} marchava sobre {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "O Despedaçamento",
			text = [=[Depois da {link:second-war}Segunda Guerra{/link}, os orcs que haviam ficado em Draenor se reuniram em torno do velho xamã. Ele reabriu o {link:dark-portal}Portal Negro{/link} e enviou guerreiros para roubar relíquias poderosas de {link:azeroth}Azeroth{/link}, pretendendo abrir passagens para novos mundos para seu povo. A {link:alliance}Aliança{/link} enviou uma expedição pelo Portal para detê-lo. Ner'zhul abriu suas passagens mesmo assim. As energias despedaçaram Draenor, e ele fugiu por uma fenda com seus seguidores.]=],
		},
		{
			title = "Feitos",
			text = [=[• Guiou os orcs como seu maior xamã.
• Liderou os clãs contra os draenei sob o engano de {link:kil-jaeden}Kil'jaeden{/link}.
• Reabriu o {link:dark-portal}Portal Negro{/link} depois da {link:second-war}Segunda Guerra{/link}.
• Despedaçou Draenor com suas passagens.
• Como Lich Rei, ergueu o {link:scourge}Flagelo{/link} e soltou a peste sobre {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[{link:kil-jaeden}Kil'jaeden{/link} o esperava além da fenda. O demônio arrancou a carne do corpo do xamã e prendeu seu espírito numa armadura e num elmo. Selou Ner'zhul num bloco de gelo e o arremessou a {link:azeroth}Azeroth{/link}. O bloco caiu na geleira da Coroa de Gelo, em {red:northrend}Nortúndria{/red}, e ali ele se tornou o Lich Rei. Do Trono de Gelo ergueu o {link:scourge}Flagelo{/link}. Chamou {link:kel-thuzad}Kel'Thuzad{/link} a seu serviço e mandou a peste para o sul. Por fim tomou o príncipe {link:arthas-menethil}Arthas Menethil{/link} por meio da espada rúnica {red:frostmourne}Gélido Lamento{/red}. Quando seu poder enfraqueceu, convocou Arthas à Coroa de Gelo, e o príncipe pôs o seu elmo. Ner'zhul e Arthas são agora um só, e o Lich Rei governa no norte.]=],
		},
	},
	bonds = {
		{ id = "gul-dan", name = "Gul'dan", note = "seu aprendiz, e seu usurpador" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "o príncipe que ele tomou e a quem se uniu" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "seu servo" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "chefe de clã de sua Horda" },
	},
})

Translate("ptBR", "archimonde", {
	title = "Archimonde",
	subtitle = "O Profanador",
	allegiance = "Legião Ardente",
	sections = {
		{
			title = "Resumo",
			text = [=[Archimonde, {link:razelikh-the-defiler}o Profanador{/link}, foi um dos grandes senhores da {link:burning-legion}Legião Ardente{/link}, abaixo apenas de seu mestre sombrio, {link:sargeras}Sargeras{/link}. Foi outrora um líder dos eredar, um povo orgulhoso de outro mundo, até que Sargeras lhes ofereceu poder e ele aceitou. Travou as guerras da Legião por incontáveis mundos. Em {link:azeroth}Azeroth{/link}, chegou mais perto do que qualquer demônio antes dele de devorar o mundo, e morreu ao pé da Árvore do Mundo.]=],
		},
		{
			title = "Importância",
			text = [=[A invasão de Archimonde na {link:third-war}Terceira Guerra{/link} foi o maior ataque demoníaco que o mundo conhecera desde a {link:war-of-the-ancients}Guerra dos Antigos{/link}. Sua derrota no {link:mount-hyjal}Monte Hyjal{/link} forjou uma paz inquieta entre {link:orcs}orcs{/link}, {link:humans}humanos{/link} e {link:night-elves}elfos noturnos{/link}, uma paz que desde então molda {link:kalimdor}Kalimdor{/link}.]=],
		},
		{
			title = "Os Eredar",
			text = [=[Há muito tempo, os eredar eram governados por três líderes: Archimonde, {link:kil-jaeden}Kil'jaeden{/link} e Velen. {link:sargeras}Sargeras{/link} veio a eles com uma oferta de conhecimento e poder. Archimonde e Kil'jaeden aceitaram, e foram deformados em demônios. Velen recusou e fugiu com seus seguidores. Archimonde tornou-se um dos maiores tenentes de Sargeras. Na {link:war-of-the-ancients}Guerra dos Antigos{/link}, dez mil anos atrás, a Legião veio a {link:azeroth}Azeroth{/link} através do {link:well-of-eternity}Poço da Eternidade{/link}. Foi repelida quando o Poço foi destruído.]=],
		},
		{
			title = "A Terceira Guerra",
			text = [=[A Legião voltou muitas eras depois. Quando o {link:scourge}Flagelo{/link} já devastara {link:lordaeron}Lordaeron{/link}, o lich {link:kel-thuzad}Kel'Thuzad{/link} usou o grimório de {link:medivh}Medivh{/link} para invocar Archimonde na cidade de {link:dalaran}Dalaran{/link}. O senhor demoníaco destruiu {link:city-of-dalaran}a cidade dos magos{/link} com um único golpe de seu poder. Depois levou a Legião a {link:kalimdor}Kalimdor{/link}, onde as últimas águas do {link:well-of-eternity}Poço da Eternidade{/link} jaziam sob a Árvore do Mundo, {link:nordrassil}Nordrassil{/link}. Pretendia drenar seu poder e consumir o mundo.]=],
		},
		{
			title = "Feitos",
			text = [=[• Aceitou a oferta de {link:sargeras}Sargeras{/link} e tornou-se um senhor da Legião.
• Guerreou contra {link:azeroth}Azeroth{/link} na {link:war-of-the-ancients}Guerra dos Antigos{/link}.
• Foi invocado em {link:dalaran}Dalaran{/link} por {link:kel-thuzad}Kel'Thuzad{/link} e a destruiu.
• Marchou sobre o {link:mount-hyjal}Monte Hyjal{/link} para drenar o poder de {link:nordrassil}Nordrassil{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Na {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link}, os orcs de {link:thrall}Thrall{/link}, os homens de {link:jaina-proudmoore}Jaina Proudmoore{/link} e os elfos noturnos de {link:tyrande-whisperwind}Tyrande Whisperwind{/link} e {link:malfurion-stormrage}Malfurion Stormrage{/link} defenderam as encostas da montanha o quanto puderam. Archimonde enfim subiu até a Árvore do Mundo. Malfurion soou a Trompa de {link:cenarius}Cenarius{/link}, e uma vasta hoste de espíritos dos antigos envolveu o senhor demoníaco e o destruiu numa grande explosão. O poder de {link:nordrassil}Nordrassil{/link} se esgotou, e os elfos noturnos perderam a imortalidade. Mas a invasão da Legião foi quebrada. Seus demônios ainda rondam os bosques corrompidos da {link:felwood}Selva Maleva{/link}, e sua sombra não deixou o mundo.]=],
		},
	},
	bonds = {
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "invocou-o a Azeroth" },
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "causou sua destruição" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "inimigo na Terceira Guerra" },
		{ id = "queen-azshara", name = "Rainha Azshara", note = "que abriu o caminho da Legião nos tempos antigos" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "matou seu servo Mannoroth" },
	},
})

Translate("ptBR", "illidan-stormrage", {
	title = "Illidan Stormrage",
	subtitle = "O Traidor",
	allegiance = "Desconhecida (antes a resistência kaldorei)",
	aliases = { "Illidan", "o Traidor" },
	sections = {
		{
			title = "Resumo",
			text = [=[Illidan Stormrage foi um feiticeiro {link:night-elves}elfo noturno{/link} do mundo antigo, irmão gêmeo de {link:malfurion-stormrage}Malfurion Stormrage{/link} e rival no amor de {link:tyrande-whisperwind}Tyrande Whisperwind{/link}. Lutou contra a {link:burning-legion}Legião Ardente{/link}, e também a serviu. Ficou preso por dez mil anos e foi libertado na {link:third-war}Terceira Guerra{/link}. Alguns o chamam de herói, e muitos o chamam de traidor. Seu próprio povo o chamou de o Traidor.]=],
		},
		{
			title = "Importância",
			text = [=[As escolhas de Illidan salvaram e ameaçaram o mundo em igual medida. Nos tempos antigos, levou as águas do {link:well-of-eternity}Poço da Eternidade{/link} ao {link:mount-hyjal}Monte Hyjal{/link}, onde ainda jazem sob {link:nordrassil}Nordrassil{/link}. Na {link:third-war}Terceira Guerra{/link}, matou um senhor da Legião e tomou seu poder para si.]=],
		},
		{
			title = "A Guerra dos Antigos",
			text = [=[Illidan nasceu com olhos cor de âmbar, sinal que, diziam, prenunciava grandeza. Era atraído pela {link:arcane-magic}magia arcana{/link} como o irmão era atraído pelo caminho de {link:cenarius}Cenarius{/link}. Na {link:war-of-the-ancients}Guerra dos Antigos{/link}, lutou ao lado dos elfos noturnos contra a {link:queen-azshara}Rainha Azshara{/link} e seus aliados demoníacos. Mas tornou-se invejoso do irmão e faminto de poder, e acabou indo ao próprio {link:sargeras}Sargeras{/link}. O senhor demoníaco queimou-lhe os olhos e deu-lhe uma nova visão. Quando o {link:well-of-eternity}Poço da Eternidade{/link} foi destruído, Illidan despejou frascos roubados de sua água num lago no alto do {link:mount-hyjal}Monte Hyjal{/link}, criando um novo Poço. {link:malfurion-stormrage}Malfurion{/link} julgou isso um crime. Mandou acorrentar o irmão sob a terra, vigiado pela carcereira Maiev Shadowsong.]=],
		},
		{
			title = "A Terceira Guerra",
			text = [=[Dez mil anos depois, o {link:scourge}Flagelo{/link} e a Legião chegaram a {link:kalimdor}Kalimdor{/link}. Contra a lei de seu povo, {link:tyrande-whisperwind}Tyrande{/link} libertou Illidan para que ajudasse. Na floresta hoje chamada {link:felwood}Selva Maleva{/link}, ele consumiu o Crânio de {link:gul-dan}Gul'dan{/link}, assumiu a forma de um demônio e matou o senhor do terror {link:tichondrius}Tichondrius{/link}. {link:malfurion-stormrage}Malfurion{/link} o baniu das florestas dos elfos noturnos.]=],
		},
		{
			title = "Feitos",
			text = [=[• Lutou contra {link:azshara}Azshara{/link} na {link:war-of-the-ancients}Guerra dos Antigos{/link}.
• Criou um novo {link:well-of-eternity}Poço da Eternidade{/link} no alto do {link:mount-hyjal}Monte Hyjal{/link}.
• Consumiu o {link:skull-of-gul-dan}Crânio de Gul'dan{/link} e matou {link:tichondrius}Tichondrius{/link}.
• Ergueu os nagas das profundezas para servi-lo depois da {link:third-war}Terceira Guerra{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Depois de banido, Illidan reuniu os {link:naga}nagas{/link} e buscou a Tumba de {link:sargeras}Sargeras{/link} sob o mar. Foi perseguido por Maiev, e por seu irmão e {link:tyrande-whisperwind}Tyrande{/link}, e escapou de todos. Mais tarde marchou sobre {red:northrend}Nortúndria{/red} para golpear o {red:lich-king}Lich Rei{/red}. Na geleira da Coroa de Gelo, lutou contra {link:arthas-menethil}Arthas Menethil{/link} e foi derrotado. Fugiu com os seguidores que lhe restavam. Para onde foi depois disso, nenhuma crônica dos reinos sabe dizer.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "seu irmão gêmeo" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "o amor que ele perdeu" },
		{ id = "queen-azshara", name = "Rainha Azshara", note = "inimiga de outrora" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "derrotou-o na Coroa de Gelo" },
		{ id = "gul-dan", name = "Gul'dan", note = "cujo crânio ele consumiu" },
	},
})

Translate("ptBR", "malfurion-stormrage", {
	title = "Malfurion Stormrage",
	subtitle = "O Primeiro Druida",
	allegiance = "Elfos Noturnos · Círculo Cenariano",
	aliases = { "Malfurion" },
	sections = {
		{
			title = "Resumo",
			text = [=[Malfurion Stormrage foi o primeiro druida {link:night-elves}elfo noturno{/link}, aluno do semideus {link:cenarius}Cenarius{/link} e irmão gêmeo de {link:illidan-stormrage}Illidan Stormrage{/link}. Liderou a luta contra a {link:burning-legion}Legião Ardente{/link} na {link:war-of-the-ancients}Guerra dos Antigos{/link} e de novo na {link:third-war}Terceira Guerra{/link}. É o amado de {link:tyrande-whisperwind}Tyrande Whisperwind{/link}. Hoje dorme no {link:emerald-dream}Sonho Esmeralda{/link}, e seu povo espera que ele desperte.]=],
		},
		{
			title = "Importância",
			text = [=[Malfurion salvou o mundo duas vezes. Nos tempos antigos, destruiu o {link:well-of-eternity}Poço da Eternidade{/link} para fechar a porta à Legião. Dez mil anos depois, destruiu {link:archimonde}Archimonde{/link} ao pé da Árvore do Mundo. Os druidas de todas as terras seguem o caminho que ele percorreu primeiro.]=],
		},
		{
			title = "A Guerra dos Antigos",
			text = [=[Malfurion era atraído pelo mundo vivo enquanto o irmão estudava o arcano. {link:cenarius}Cenarius{/link} o tomou como aluno e ensinou-o a moldar os poderes da natureza. Quando a {link:queen-azshara}Rainha Azshara{/link} e seus Bem-nascidos trouxeram a Legião ao mundo, Malfurion juntou-se à resistência. Viu que a Legião só poderia ser detida com a destruição do próprio {link:well-of-eternity}Poço da Eternidade{/link}. Seu ataque contra ele desencadeou a {link:great-sundering}Grande Cisão{/link}, que despedaçou a terra e afogou a capital da rainha. Quando {link:illidan-stormrage}Illidan{/link} criou um novo Poço no {link:mount-hyjal}Monte Hyjal{/link}, Malfurion o fez aprisionar. Com a ajuda dos grandes dragões, os sobreviventes plantaram {link:nordrassil}Nordrassil{/link} sobre o novo Poço. Malfurion e seus druidas então entraram num longo sono no {link:emerald-dream}Sonho Esmeralda{/link}.]=],
		},
		{
			title = "A Terceira Guerra",
			text = [=[Quando a Legião voltou, {link:tyrande-whisperwind}Tyrande{/link} despertou os druidas. Malfurion os trouxe de volta ao mundo e ajudou a defender as florestas do {link:ashenvale}Vale Gris{/link} contra os demônios. Contra a vontade dele, Tyrande libertou {link:illidan-stormrage}Illidan{/link}, e ele chegou tarde demais para impedir que o irmão tomasse o poder de um demônio. Baniu Illidan e voltou à defesa de Hyjal. Ali lutou ao lado dos orcs de {link:thrall}Thrall{/link} e dos homens de {link:jaina-proudmoore}Jaina Proudmoore{/link}. Quando {link:archimonde}Archimonde{/link} chegou a {link:nordrassil}Nordrassil{/link}, Malfurion soou a Trompa de {link:cenarius}Cenarius{/link}. Os espíritos dos antigos destruíram o senhor demoníaco, e o mundo foi salvo.]=],
		},
		{
			title = "Feitos",
			text = [=[• Aprendeu os caminhos da natureza com {link:cenarius}Cenarius{/link} e tornou-se o primeiro druida.
• Destruiu o {link:well-of-eternity}Poço da Eternidade{/link} e encerrou a {link:war-of-the-ancients}Guerra dos Antigos{/link}.
• Aprisionou o irmão sob a terra.
• Liderou os druidas contra a Legião na {link:third-war}Terceira Guerra{/link}.
• Destruiu {link:archimonde}Archimonde{/link} na {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Depois da guerra, Malfurion caçou {link:illidan-stormrage}Illidan{/link} através do mar, e depois o deixou ir. Voltou ao {link:emerald-dream}Sonho Esmeralda{/link} e não despertou desde então. Em sua ausência, o Arquidruida {link:fandral-staghelm}Fandral Staghelm{/link} lidera os druidas de {link:darnassus}Darnassus{/link}, e os elfos noturnos plantaram uma nova Árvore do Mundo, {link:teldrassil}Teldrassil{/link}. {link:tyrande-whisperwind}Tyrande{/link} governa e espera.]=],
		},
	},
	bonds = {
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "seu irmão gêmeo" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "sua amada" },
		{ id = "archimonde", name = "Archimonde", note = "o demônio que ele destruiu" },
		{ id = "queen-azshara", name = "Rainha Azshara", note = "a rainha que ele combateu" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "lidera os druidas em seu lugar" },
	},
})

Translate("ptBR", "queen-azshara", {
	title = "Rainha Azshara",
	subtitle = "Rainha dos Bem-nascidos",
	allegiance = "Bem-nascidos · Nagas",
	sections = {
		{
			title = "Resumo",
			text = [=[A Rainha Azshara governou o antigo império dos {link:night-elves}elfos noturnos{/link} no auge de sua glória. Era a mais bela e a mais poderosa de seu povo, e ele a adorava. De seu palácio em Zin-Azshari, junto ao {link:well-of-eternity}Poço da Eternidade{/link}, guiou os Bem-nascidos no estudo da {link:arcane-magic}magia arcana{/link}. Em seu orgulho, abriu o mundo à {link:burning-legion}Legião Ardente{/link}, e seu império afundou sob o mar.]=],
		},
		{
			title = "Importância",
			text = [=[A traição de {link:azshara}Azshara{/link} deu início à {link:war-of-the-ancients}Guerra dos Antigos{/link} e terminou na {link:great-sundering}Grande Cisão{/link}. A forma partida de {link:kalimdor}Kalimdor{/link} e dos {link:eastern-kingdoms}Reinos do Leste{/link} é o seu legado. Talvez também o sejam os {link:naga}nagas{/link} que hoje se erguem das ondas.]=],
		},
		{
			title = "A Rainha dos Bem-nascidos",
			text = [=[O povo de {link:azshara}Azshara{/link} deu seu nome a cidades e montanhas. Os Bem-nascidos, a casta nobre de sua corte, serviam-na como sacerdotes e feiticeiros. Sob seu governo, beberam cada vez mais fundo do {link:well-of-eternity}Poço da Eternidade{/link}. Seus feitiços alcançaram além do mundo e atraíram o olhar de {link:sargeras}Sargeras{/link}. O senhor demoníaco sussurrou à rainha, e ela ouviu. Passou a acreditar que o mundo devia ser purificado de todos os povos inferiores, e que Sargeras faria isso.]=],
		},
		{
			title = "A Guerra dos Antigos",
			text = [=[{link:azshara}Azshara{/link} e seus Bem-nascidos abriram um portal dentro do Poço, e os demônios da Legião jorraram por ele. Seu conselheiro Xavius serviu-a nessa obra. Os elfos noturnos que permaneceram livres se levantaram contra a rainha, liderados por {link:malfurion-stormrage}Malfurion Stormrage{/link}, {link:tyrande-whisperwind}Tyrande Whisperwind{/link} e Lorde Kur'talos Ravencrest. Enquanto a guerra rugia, os Bem-nascidos trabalhavam para trazer o próprio {link:sargeras}Sargeras{/link} ao mundo. Só foram detidos quando o Poço foi destruído. Seu colapso rasgou a terra, e o mar avançou sobre Zin-Azshari.]=],
		},
		{
			title = "Feitos",
			text = [=[• Governou os elfos noturnos no auge de seu poder.
• Guiou os Bem-nascidos no uso do {link:well-of-eternity}Poço da Eternidade{/link}.
• Abriu o caminho da {link:burning-legion}Legião Ardente{/link} para {link:azeroth}Azeroth{/link}.
• Buscou trazer o próprio {link:sargeras}Sargeras{/link} ao mundo.]=],
		},
		{
			title = "Destino",
			text = [=[Quando o Poço desmoronou, Azshara e seus Bem-nascidos desapareceram sob as ondas. As lendas dos elfos noturnos dizem que não morreram, mas foram transformados, e que os serpentinos nagas são o que se tornaram. Os nagas voltaram às praias nestes dias, atacando as costas de {link:kalimdor}Kalimdor{/link} e de outras terras. Alguns deles falam de sua antiga rainha como se ela ainda vivesse. Só as ruínas de seu império restam na terra que leva seu nome, {link:azshara}Azshara{/link}.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhum registro mortal diz se {link:azshara}Azshara{/link} ainda vive sob o mar, nem no que ela se tornou.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "liderou a rebelião contra ela" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "combateu sua corte" },
		{ id = "archimonde", name = "Archimonde", note = "um senhor da Legião a quem ela serviu" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "liderou a rebelião contra ela" },
	},
})

Translate("ptBR", "deathwing", {
	title = "Asa da Morte",
	subtitle = "O Destruidor",
	allegiance = "Revoada Dragônica Negra",
	aliases = { "Neltharion" },
	sections = {
		{
			title = "Resumo",
			text = [=[Asa da Morte foi outrora Neltharion, o Guardião da Terra, Aspecto da Revoada {link:the-drag}Drag{/link}ônica Negra. Tinha a missão de guardar os lugares profundos do mundo. A loucura o tomou, e ele traiu as outras revoadas na {link:war-of-the-ancients}Guerra dos Antigos{/link}. Desde então trama contra todos os povos de {link:azeroth}Azeroth{/link}. Seu nome significa ruína para dragões e mortais.]=],
		},
		{
			title = "Importância",
			text = [=[A traição de Asa da Morte quase destruiu as revoadas. Sua intromissão na {link:second-war}Segunda Guerra{/link} deu à {link:horde}Horda{/link} os seus dragões. Sua ninhada negra ainda assombra a {link:blackrock-mountain}Montanha Rocha Negra{/link} e outros lugares sombrios do mundo.]=],
		},
		{
			title = "O Guardião da Terra",
			text = [=[Nos dias antigos, cinco grandes dragões foram escolhidos como Aspectos para guardar o mundo. Neltharion recebeu o domínio sobre a terra e suas profundezas. Algo lhe sussurrou das entranhas da pedra, e com o tempo sua mente se desvirtuou. Na {link:war-of-the-ancients}Guerra dos Antigos{/link}, forjou um grande disco de ouro, a Alma do {link:the-drag}Drag{/link}ão. Convenceu os outros Aspectos a lhe dar parte de seu poder, dizendo que ele repeliria a {link:burning-legion}Legião Ardente{/link}. Em vez disso, voltou-o contra eles. O poder do artefato era tão grande que seu corpo começou a se rasgar, e placas de metal foram presas a seu couro para mantê-lo inteiro. Ele fugiu, e a Alma do Dragão se perdeu.]=],
		},
		{
			title = "A Segunda Guerra",
			text = [=[Asa da Morte há muito anda entre os mortais sob disfarce humano, como um nobre que circula pelas cortes dos reis. As histórias dizem que ele semeou discórdia onde pôde. Na {link:second-war}Segunda Guerra{/link}, a Alma do {link:the-drag}Drag{/link}ão caiu nas mãos dos {link:dragonmaw-clan}orcs Presa do Dragão{/link}. Com ela, capturaram {link:alexstrasza}Alexstrasza{/link}, Aspecto dos dragões vermelhos, e a mantiveram sob {link:grim-batol}Grim Batol{/link}. Seus filhotes foram criados como montarias de guerra para a {link:horde}Horda{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Traiu os Aspectos com a Alma do {link:the-drag}Drag{/link}ão na {link:war-of-the-ancients}Guerra dos Antigos{/link}.
• Circulou em segredo pelas cortes dos homens.
• Deixou a Alma do Dragão cair nas mãos do {link:dragonmaw-clan}clã Presa do Dragão{/link}.
• Tentou roubar os ovos da Revoada Dragônica Vermelha em {link:grim-batol}Grim Batol{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Depois da {link:second-war}Segunda Guerra{/link}, os {link:dragonmaw-clan}Presa do Dragão{/link} ainda mantinham {link:alexstrasza}Alexstrasza{/link} cativa em {link:grim-batol}Grim Batol{/link}. Asa da Morte veio buscar seus ovos, para reconstruir a própria revoada. Um pequeno grupo de heróis e dragões libertou a rainha vermelha, e a Alma do {link:the-drag}Drag{/link}ão foi destruída. Asa da Morte foi rechaçado em fúria. Para onde foi, ninguém sabe. A montanha de Grim Batol, no {link:wetlands}Pantanal{/link}, é evitada pelos anões até hoje. Seus filhos e sua Revoada Dragônica Negra ainda andam pelo mundo.]=],
		},
	},
	bonds = {
		{ id = "alexstrasza", name = "Alexstrasza", note = "o Aspecto que ele ajudou a escravizar" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "chefe guerreiro da Horda que usou seu presente" },
		{ id = "queen-azshara", name = "Rainha Azshara", note = "aliada da Legião que ele dizia combater" },
	},
})

Translate("ptBR", "kel-thuzad", {
	title = "Kel'Thuzad",
	subtitle = "Fundador do Culto dos Malditos",
	allegiance = "Flagelo · Culto dos Malditos (antes Kirin Tor)",
	sections = {
		{
			title = "Resumo",
			text = [=[Kel'Thuzad foi outrora arquimago de {link:dalaran}Dalaran{/link} e membro do conselho governante do {link:kirin-tor}Kirin Tor{/link}. Voltou-se para a arte proibida da necromancia, jurou lealdade ao {red:lich-king}Lich Rei{/red} e fundou o {link:cult-of-the-damned}Culto dos Malditos{/link}. Espalhou a peste que destruiu {link:lordaeron}Lordaeron{/link}. Morto pelo Príncipe {link:arthas-menethil}Arthas Menethil{/link}, ergueu-se de novo como lich. Hoje comanda o {link:scourge}Flagelo{/link} em Lordaeron em nome de seu mestre.]=],
		},
		{
			title = "Importância",
			text = [=[Sem Kel'Thuzad, a peste de mortos-vivos talvez nunca tivesse chegado ao povo de {link:lordaeron}Lordaeron{/link}. Ele foi a voz do Lich Rei entre os vivos, e abriu o caminho para a volta da {link:burning-legion}Legião Ardente{/link} a {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "O Arquimago",
			text = [=[Kel'Thuzad era um dos maiores {link:the-wizards-of-ambermill}magos de Dalaran{/link}, mas achava seus colegas tímidos demais em seus estudos. Começou a se aprofundar na arte sombria da necromancia. Quando o conselho a proibiu, ele não parou. Uma voz o chamou de {red:northrend}Nortúndria{/red}. Ele respondeu, viajou ao norte gelado e jurou-se ao Lich Rei. Seu mestre lhe prometeu a vida eterna.]=],
		},
		{
			title = "O Culto dos Malditos",
			text = [=[Kel'Thuzad voltou a {link:lordaeron}Lordaeron{/link} e falou aos pobres e aos cansados de uma nova sociedade onde todos seriam iguais e ninguém morreria. Milhares se juntaram a seu {link:cult-of-the-damned}Culto dos Malditos{/link}. Por meio deles, contaminou os grãos dos celeiros do norte com uma peste que transformava os vivos em mortos-vivos. Quando {link:arthas-menethil}Arthas{/link} veio ao norte combater a peste, encontrou Kel'Thuzad em {link:ruins-of-andorhal}Andorhal{/link} e o matou. Mas o espírito do necromante permaneceu, e sussurrou ao príncipe enquanto este caía.]=],
		},
		{
			title = "Feitos",
			text = [=[• Estudou necromancia desafiando o {link:kirin-tor}Kirin Tor{/link}.
• Jurou-se ao Lich Rei em Nortúndria.
• Fundou o {link:cult-of-the-damned}Culto dos Malditos{/link}.
• Espalhou a peste de mortos-vivos pelos grãos de {link:lordaeron}Lordaeron{/link}.
• Invocou {link:archimonde}Archimonde{/link} em {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Quando {link:arthas-menethil}Arthas{/link} se tornou servo do Lich Rei, levou os restos do necromante a {link:quel-thalas}Quel'Thalas{/link}. Ali, nas águas da Nascente do Sol, Kel'Thuzad renasceu como lich. Com o grimório de {link:medivh}Medivh{/link}, invocou {link:archimonde}Archimonde{/link} em {link:dalaran}Dalaran{/link}, e o senhor demoníaco pôs a cidade em ruínas. Quando Arthas voltou a Nortúndria, Kel'Thuzad ficou para governar o {link:scourge}Flagelo{/link} em {link:lordaeron}Lordaeron{/link}. Ainda o faz. A grande necrópole de {red:naxxramas}Naxxramas{/red} flutua sobre as Terras Pestilentas, e seus cultistas mantêm sua escola de saber sombrio no velho castelo de {link:caer-darrow}Castro das Flechas{/link}.]=],
		},
	},
	bonds = {
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "seu matador, depois seu mestre" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "o Lich Rei a quem ele se jurou" },
		{ id = "archimonde", name = "Archimonde", note = "o demônio que ele invocou" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "cujas cinzas deram lugar a seus ossos" },
	},
})

Translate("ptBR", "jaina-proudmoore", {
	title = "Jaina Proudmoore",
	subtitle = "Soberana de Theramore",
	found = "Cidadela do Esteio, Ilha Theramore, no Pântano Vadeoso",
	hint = [=[Procure a senhora de Theramore na torre da cidadela de sua ilha.]=],
	allegiance = "Theramore · Aliança · Kirin Tor",
	aliases = { "Jaina", "Lady Jaina Proudmoore", "Lady Proudmoore" },
	sections = {
		{
			title = "Resumo",
			text = [=[Lady Jaina Proudmoore governa {link:theramore-isle}Theramore{/link}, a fortaleza insular da {link:alliance}Aliança{/link} na costa leste de {link:kalimdor}Kalimdor{/link}. É filha do Grão-almirante {link:daelin-proudmoore}Daelin Proudmoore{/link}, de {link:kul-tiras}Kul Tiraz{/link}, e uma feiticeira treinada em {link:dalaran}Dalaran{/link} pelo {link:kirin-tor}Kirin Tor{/link}. Caminhou ao lado do Príncipe {link:arthas-menethil}Arthas Menethil{/link} nos dias da peste, e separou-se dele antes de sua queda. Guiou os sobreviventes do norte através do mar e fez com a {link:horde}Horda{/link} uma paz que ninguém antes dela julgara possível.]=],
		},
		{
			title = "Importância",
			text = [=[Jaina é a ponte entre os velhos inimigos. Esteve com {link:thrall}Thrall{/link} na {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link} e mantém-se fiel a ele até hoje. Essa paz lhe custou o pai. É frágil, e muitos dos dois lados gostariam de vê-la rompida.]=],
		},
		{
			title = "A Peste",
			text = [=[Quando jovem, Jaina estudou magia em {link:dalaran}Dalaran{/link} sob o arquimago Antonidas e mostrou dons raros. Quando uma estranha peste se espalhou pelas terras agrícolas do norte de {link:lordaeron}Lordaeron{/link}, foi com o {link:arthas-menethil}Príncipe Arthas{/link} descobrir sua origem. Juntos descobriram o {link:cult-of-the-damned}Culto dos Malditos{/link} e os grãos contaminados. Em Stratholme, Arthas ordenou que o povo da cidade fosse morto antes que se erguesse como morto-vivo. Jaina não quis participar e o deixou ali. O {link:culling-of-stratholme}Expurgo de Stratholme{/link} prosseguiu sem ela.]=],
		},
		{
			title = "A Jornada ao Oeste",
			text = [=[Um profeta misterioso instou os líderes do leste a navegar para o oeste, através do mar. Jaina o ouviu quando outros não ouviram, e guiou os sobreviventes de {link:lordaeron}Lordaeron{/link} até {link:kalimdor}Kalimdor{/link}. Ali encontrou {link:thrall}Thrall{/link} e seus orcs, os velhos inimigos de seu povo. O profeta os uniu contra um inimigo maior, e no {link:mount-hyjal}Monte Hyjal{/link} humanos, orcs e {link:night-elves}elfos noturnos{/link} lutaram lado a lado até que {link:archimonde}Archimonde{/link} fosse destruído.]=],
		},
		{
			title = "Feitos",
			text = [=[• Estudou magia entre o {link:kirin-tor}Kirin Tor{/link} de {link:dalaran}Dalaran{/link}.
• Caçou a peste com {link:arthas-menethil}Arthas{/link} e recusou o {link:culling-of-stratholme}Expurgo de Stratholme{/link}.
• Guiou os sobreviventes de {link:lordaeron}Lordaeron{/link} para o oeste, até {link:kalimdor}Kalimdor{/link}.
• Lutou ao lado de {link:thrall}Thrall{/link} e dos elfos noturnos no {link:mount-hyjal}Monte Hyjal{/link}.
• Fundou {link:theramore-isle}Theramore{/link} e fez a paz com a {link:horde}Horda{/link}.]=],
		},
		{
			title = "Theramore",
			text = [=[Depois da guerra, Jaina ergueu {link:theramore-isle}Theramore{/link} numa ilha junto à costa do {link:dustwallow-marsh}Pântano Vadeoso{/link}. Então seu pai veio a {link:kalimdor}Kalimdor{/link} com uma grande frota. {link:daelin-proudmoore}Daelin{/link} não aceitava uma paz com os orcs, e fez guerra contra eles. Jaina não conseguiu convencê-lo a parar. Não o deixaria destruir a paz, e afastou-se enquanto a {link:horde}Horda{/link} se defendia. Daelin foi morto na luta diante das muralhas de Theramore. Sua filha está de luto, e os marinheiros que o seguiam não a perdoaram.]=],
		},
		{
			title = "Os Dias de Hoje",
			text = [=[Jaina governa {link:theramore-isle}Theramore{/link} de sua cidadela. A cidade é um refúgio para o povo do norte perdido e uma porta de entrada da {link:alliance}Aliança{/link} em {link:kalimdor}Kalimdor{/link}. Ela mantém a paz com {link:thrall}Thrall{/link} como pode, enquanto os soldados dos dois lados se enfrentam nos ermos.]=],
		},
	},
	chapters = {
		{
			title = "O Diplomata Desaparecido",
			hint = "Siga a trilha do diplomata desaparecido até Theramore.",
			text = [=[A trilha de um enviado roubado levava de {link:stormwind-city}Ventobravo{/link} ao {link:menethil-harbor}Porto de Menethil{/link}, e dali, através do mar, ao {link:dustwallow-marsh}Pântano Vadeoso{/link}. Em seu fim estava o {link:private-hendel}Soldado Hendel{/link}, um soldado de {link:theramore-isle}Theramore{/link} que se vendera à {link:defias-brotherhood}Irmandade Défias{/link}. Quando foi desmascarado, sacou a lâmina. Jaina e seus guardas vieram levá-lo vivo, pois um traidor morto nada conta. A senhora de Theramore agradeceu discretamente aos que haviam trazido a verdade à luz. Não podia agradecer-lhes em público. O que Hendel sabe do rei desaparecido de Ventobravo é assunto para seus interrogadores.]=],
		},
	},
	mentions = {
		{ text = "The Missing Diplomat" },
		{ text = "The Missing Diplomat" },
	},
	bonds = {
		{ id = "daelin-proudmoore", name = "Daelin Proudmoore", note = "seu pai" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "seu companheiro, e seu amor perdido" },
		{ id = "thrall", name = "Thrall", note = "seu aliado na paz" },
		{ id = "aegwynn", name = "Aegwynn", note = "dizem que a aconselhou" },
		{ id = "tapoke-slim-jahn", name = "Tapoke \"Slim\" Jahn", note = "ajudou na conspiração que seus guardas descobriram" },
	},
})

Translate("ptBR", "khadgar", {
	title = "Khadgar",
	subtitle = "Aprendiz do Último Guardião",
	allegiance = "Kirin Tor · Aliança de Lordaeron",
	sections = {
		{
			title = "Resumo",
			text = [=[Khadgar foi um jovem mago de {link:dalaran}Dalaran{/link} enviado pelo {link:kirin-tor}Kirin Tor{/link} para servir como aprendiz de {link:medivh}Medivh{/link}, o último Guardião de {link:tirisfal-glades}Tirisfal{/link}. Foi o primeiro a ver que o próprio Guardião trouxera os orcs a {link:azeroth}Azeroth{/link}. Lutou na {link:first-war}Primeira Guerra{/link} e na {link:second-war}Segunda Guerra{/link} e tornou-se um dos grandes arquimagos de sua era. Atravessou o {link:dark-portal}Portal Negro{/link} há muito tempo, e não voltou.]=],
		},
		{
			title = "Importância",
			text = [=[Khadgar trouxe a verdade para fora de {link:karazhan}Karazhan{/link}. Sem ele, {link:stormwind-city}Ventobravo{/link} talvez nunca soubesse quem era seu verdadeiro inimigo. Na {link:second-war}Segunda Guerra{/link}, esteve ao lado de {link:anduin-lothar}Anduin Lothar{/link} como um dos líderes da {link:alliance}Aliança{/link}, e no fim fechou o caminho entre os mundos ao custo de seu próprio retorno.]=],
		},
		{
			title = "Karazhan",
			text = [=[Os {link:the-wizards-of-ambermill}magos de Dalaran{/link} desejavam havia muito conhecer os segredos da {link:karazhan}torre de Medivh{/link}. Enviaram Khadgar como seu aprendiz e mandaram-no observar. O Guardião o acolheu e o ensinou. Khadgar logo percebeu que seu mestre tinha longos silêncios, visões estranhas e uma escuridão de que não falava. Com a meio-{link:orcs}orc{/link} {link:garona}Garona{/link}, que veio à torre como enviada da {link:horde}Horda{/link}, descobriu que o próprio {link:medivh}Medivh{/link} abrira o {link:dark-portal}Portal Negro{/link}. Os dois levaram o aviso ao Rei {link:llane-wrynn}Llane Wrynn{/link}. Então Khadgar subiu Karazhan com {link:anduin-lothar}Lothar{/link} para enfrentar seu mestre. Medivh foi morto. Naquela batalha, o jovem mago envelheceu muitos anos num instante, e desceu da torre com o rosto de um velho.]=],
		},
		{
			title = "A Segunda Guerra",
			text = [=[Khadgar foi para o norte com {link:anduin-lothar}Lothar{/link} e os exilados de {link:stormwind-city}Ventobravo{/link}. Em {link:lordaeron}Lordaeron{/link}, foi um dos tenentes do campeão, junto com o paladino {link:turalyon}Turalyon{/link}. Combateu a {link:horde}Horda{/link} pelos reinos do norte e ajudou a derrotá-la na {link:blackrock-mountain}Montanha Rocha Negra{/link}. Quando a guerra foi vencida, a {link:alliance}Aliança{/link} destruiu o {link:dark-portal}Portal Negro{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Serviu como o último aprendiz de {link:medivh}Medivh{/link} em {link:karazhan}Karazhan{/link}.
• Descobriu o papel de Medivh na vinda dos orcs e avisou o {link:llane-wrynn}Rei Llane{/link}.
• Lutou ao lado de {link:anduin-lothar}Anduin Lothar{/link} quando Medivh foi morto.
• Serviu como tenente da {link:alliance}Aliança{/link} na {link:second-war}Segunda Guerra{/link}.
• Liderou a Aliança além do {link:dark-portal}Portal Negro{/link} depois da guerra.]=],
		},
		{
			title = "Além do Portal",
			text = [=[Alguns anos depois da {link:second-war}Segunda Guerra{/link}, o Portal se abriu mais uma vez. {link:orcs}Orcs{/link} vieram de {red:draenor}Draenor{/red} por ele para roubar relíquias de poder, enviados pelo velho xamã {link:ner-zhul}Ner'zhul{/link}. A {link:alliance}Aliança{/link} mandou um exército atrás deles até o mundo natal dos orcs. Khadgar o liderou com {link:turalyon}Turalyon{/link}. Os feitiços de Ner'zhul despedaçaram Draenor. Para impedir que a ruína se derramasse sobre {link:azeroth}Azeroth{/link}, os líderes da Aliança escolheram fechar o Portal do outro lado. Sabiam que não poderiam voltar para casa. O Portal silenciou, e a expedição se perdeu para seu povo.]=],
		},
		{
			title = "Destino",
			text = [=[Nenhuma notícia de Khadgar chegou aos reinos desde que o Portal foi fechado. Na {link:blasted-lands}Barreira do Inferno{/link}, os magos do {link:kirin-tor}Kirin Tor{/link} vigiam o portal arruinado a partir da fortaleza de {link:nethergarde-keep}Etergarde{/link}, e não o esqueceram.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhuma crônica dos reinos conta o que foi feito de Khadgar e de seus companheiros além do Portal.]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "Medivh", note = "seu mestre" },
		{ id = "garona", name = "Garona", note = "sua aliada em Karazhan" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "seu comandante" },
		{ id = "turalyon", name = "Turalyon", note = "seu companheiro em duas guerras" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "seu inimigo além do Portal" },
	},
})

Translate("ptBR", "turalyon", {
	title = "Turalyon",
	subtitle = "Vencedor da Segunda Guerra",
	allegiance = "Cavaleiros do Punho de Prata · Aliança de Lordaeron",
	sections = {
		{
			title = "Resumo",
			text = [=[Turalyon foi um jovem sacerdote da {link:holy-light}Luz Sagrada{/link} que se tornou um dos primeiros paladinos dos Cavaleiros do Punho de Prata. Serviu como tenente de {link:anduin-lothar}Anduin Lothar{/link} na {link:second-war}Segunda Guerra{/link}. Quando Lothar caiu, Turalyon assumiu seu comando e venceu a guerra. Depois liderou a {link:alliance}Aliança{/link} além do {link:dark-portal}Portal Negro{/link}, e não voltou.]=],
		},
		{
			title = "Importância",
			text = [=[Foi Turalyon quem transformou a hora mais sombria da {link:alliance}Aliança{/link} em vitória. Sua carga na {link:blackrock-mountain}Montanha Rocha Negra{/link} quebrou a antiga {link:horde}Horda{/link}, e a paz que os reinos do norte conheceram por uma geração foi um presente seu.]=],
		},
		{
			title = "O Punho de Prata",
			text = [=[Turalyon era sacerdote da igreja em {link:lordaeron}Lordaeron{/link} quando os exilados de {link:stormwind-city}Ventobravo{/link} chegaram ao norte. {link:anduin-lothar}Lothar{/link} viu força nele e o fez um de seus tenentes, com o mago {link:khadgar}Khadgar{/link}. Turalyon duvidava de si mesmo e de sua fé. Mesmo assim, estava entre os primeiros cavaleiros que o Arcebispo {link:alonsus-faol}Alonsus Faol{/link} treinou para empunhar a Luz em batalha, com {link:uther-the-lightbringer}Uther the Lightbringer{/link}, {link:tirion-fordring}Tirion Fordring{/link} e alguns outros. Liderou os exércitos da {link:alliance}Aliança{/link} contra a {link:horde}Horda{/link} no norte e aprendeu a confiar no poder que lhe fora dado.]=],
		},
		{
			title = "A Montanha Rocha Negra",
			text = [=[No fim da guerra, a {link:alliance}Aliança{/link} empurrou a {link:horde}Horda{/link} para o sul, até a {link:blackrock-mountain}Montanha Rocha Negra{/link}. Na batalha ao pé da montanha, o chefe guerreiro {link:orgrim-doomhammer}Orgrim Doomhammer{/link} matou {link:anduin-lothar}Lothar{/link}. Os soldados da Aliança vacilaram. Turalyon tomou a espada de seu comandante e os reuniu. Os paladinos invocaram a Luz, e a Horda foi quebrada. Doomhammer foi capturado. Turalyon perseguiu os últimos orcs até o {link:dark-portal}Portal Negro{/link}, e a Aliança destruiu o portal.]=],
		},
		{
			title = "Feitos",
			text = [=[• Esteve entre os primeiros paladinos do Punho de Prata.
• Serviu como tenente de {link:anduin-lothar}Anduin Lothar{/link} na {link:second-war}Segunda Guerra{/link}.
• Reuniu a {link:alliance}Aliança{/link} depois da morte de Lothar e venceu a batalha da {link:blackrock-mountain}Montanha Rocha Negra{/link}.
• Empurrou a {link:horde}Horda{/link} até o {link:dark-portal}Portal Negro{/link} e viu-o destruído.
• Levou o exército da Aliança a {red:draenor}Draenor{/red} com {link:khadgar}Khadgar{/link}.]=],
		},
		{
			title = "Além do Portal",
			text = [=[Alguns anos depois, o Portal se abriu de novo, e orcs vieram por ele roubar relíquias de poder para o xamã {link:ner-zhul}Ner'zhul{/link}. Turalyon levou o exército da {link:alliance}Aliança{/link} a Draenor com {link:khadgar}Khadgar{/link}. Com eles foram a patrulheira Alleria Windrunner, irmã mais velha de {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, e outros heróis da guerra. A expedição combateu os orcs por seu mundo partido. Quando os feitiços de Ner'zhul começaram a despedaçar Draenor, seus líderes fecharam o Portal do outro lado para que a ruína não chegasse a {link:azeroth}Azeroth{/link}. Não puderam voltar para casa.]=],
		},
		{
			title = "Destino",
			text = [=[Turalyon não foi mais visto nos reinos desde que o Portal foi fechado. Os paladinos do norte ainda pronunciam seu nome ao lado do de {link:uther-the-lightbringer}Uther{/link}.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhuma crônica dos reinos registra o que foi feito de Turalyon além do Portal.]=],
		},
	},
	bonds = {
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "seu comandante" },
		{ id = "khadgar", name = "Khadgar", note = "seu companheiro em duas guerras" },
		{ id = "uther-the-lightbringer", name = "Uther the Lightbringer", note = "um irmão do Punho de Prata" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "o chefe guerreiro que ele derrotou" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "ordenou-o" },
	},
})

Translate("ptBR", "tirion-fordring", {
	title = "Tirion Fordring",
	subtitle = "O Paladino Exilado",
	found = [=[Uma cabana solitária junto ao rio, na borda oeste das Terras Pestilentas Orientais]=],
	hint = [=[Procure o eremita que pesca junto a uma cabana na borda oeste das Terras Pestilentas Orientais.]=],
	allegiance = "Nenhuma (antes os Cavaleiros do Punho de Prata)",
	aliases = { "Tirion" },
	sections = {
		{
			title = "Resumo",
			text = [=[Tirion Fordring foi outrora senhor da Bastilha Mardenforte e um dos primeiros paladinos do Punho de Prata. Foi despojado de suas terras e títulos por defender um {link:orcs}orc{/link}, e levado ao exílio. Hoje vive sozinho numa cabana nas {link:eastern-plaguelands}Terras Pestilentas Orientais{/link}, um velho numa terra de mortos. Seu filho lidera a {link:scarlet-crusade}Cruzada Escarlate{/link} em {link:hearthglen}Amparo{/link} e acredita que o pai está morto há muito tempo.]=],
		},
		{
			title = "Importância",
			text = [=[Tirion é um homem da Luz que manteve sua honra quando sua ordem e seu reino não a mantiveram. Poucos em {link:lordaeron}Lordaeron{/link} se lembram dele. Mas os orcs que conhecem sua história o honram, e o relato de sua queda fala a todos que já tiveram de escolher entre a lei e o que é certo.]=],
		},
		{
			title = "O Punho de Prata",
			text = [=[Tirion esteve entre os primeiros cavaleiros treinados pelo Arcebispo {link:alonsus-faol}Alonsus Faol{/link}, com {link:uther-the-lightbringer}Uther the Lightbringer{/link} e {link:turalyon}Turalyon{/link}. Combateu a {link:horde}Horda{/link} na {link:second-war}Segunda Guerra{/link}. Depois da guerra, governou as terras de {link:hearthglen}Amparo{/link} a partir da Bastilha Mardenforte, com sua esposa, Karandra, e seu filho, {link:taelan-fordring}Taelan{/link}.]=],
		},
		{
			title = "O Julgamento",
			text = [=[Um dia Tirion encontrou um velho guerreiro {link:orcs}orc{/link} escondido nas ruínas perto de suas terras. Era {link:eitrigg}Eitrigg{/link}. O orc poderia tê-lo matado, e em vez disso o poupou. Tirion viu honra nele e o deixou ir. Quando seus próprios soldados vieram matar o orc, Tirion o defendeu. Por isso, foi julgado por traição. Foi despojado de suas terras e títulos e banido da ordem. Sua esposa disse ao filho que ele havia morrido, e {link:taelan-fordring}Taelan{/link} foi levado ao falso túmulo do pai.]=],
		},
		{
			title = "Feitos",
			text = [=[• Esteve entre os primeiros paladinos dos Cavaleiros do Punho de Prata.
• Combateu a {link:horde}Horda{/link} na {link:second-war}Segunda Guerra{/link}.
• Governou a Bastilha Mardenforte e as terras em torno de {link:hearthglen}Amparo{/link}.
• Poupou o {link:orcs}orc{/link} {link:eitrigg}Eitrigg{/link} e o defendeu contra os próprios homens.]=],
		},
		{
			title = "Os Dias de Hoje",
			text = [=[Tirion vive sozinho junto ao rio, longe de qualquer estrada. Seu filho {link:taelan-fordring}Taelan{/link} cresceu e tornou-se paladino, e hoje é Grão-senhor da {link:scarlet-crusade}Cruzada Escarlate{/link} em {link:hearthglen}Amparo{/link}, preso a uma ordem que perdeu o rumo. {link:eitrigg}Eitrigg{/link} serve a {link:thrall}Thrall{/link} em {link:orgrimmar}Orgrimmar{/link} e não esqueceu o homem que o salvou.]=],
		},
	},
	chapters = {
		{
			title = "Redenção",
			hint = "Sente-se com o velho junto ao rio e ouça sua história.",
			text = [=[Tirion pediu apenas que seu hóspede se sentasse e ouvisse. Contou sua queda e falou do filho, que crescera sem ele. Não pediu que seu próprio nome fosse limpo. Pediu que {link:taelan-fordring}Taelan{/link} fosse salvo daquilo que a Cruzada fizera dele.]=],
		},
		{
			title = "De Memórias Esquecidas",
			hint = [=[Recupere um brinquedo de um falso túmulo no sul das Terras Pestilentas.]=],
			text = [=[Quando {link:taelan-fordring}Taelan{/link} tinha sete anos, o pai lhe deu um pequeno martelo de guerra, uma cópia do seu. Depois do banimento de Tirion, o menino o enterrou no falso túmulo do pai, na {link:the-undercroft}Chácara Secreta{/link}. Ali jazia desde então, e Tirion pediu que o trouxessem de volta.]=],
		},
		{
			title = "De Honra Perdida",
			hint = "Recupere o que Taelan lançou ao chão no Vilarejo do Norte.",
			text = [=[Quando {link:uther-the-lightbringer}Uther{/link} caiu e o Punho de Prata foi destruído, o jovem {link:taelan-fordring}Taelan{/link} lutou enquanto pôde. No {link:northdale}Vilarejo do Norte{/link} fez sua última resistência, e ali lançou o estandarte da ordem ao chão e deu-lhe as costas. Tirion olhou o estandarte rasgado e lembrou-se do dia em que fez o próprio juramento.]=],
		},
		{
			title = "Em Sonhos",
			hint = "Leve Taelan até o pai.",
			text = [=[{link:taelan-fordring}Taelan{/link} sonhara com o pai por anos. Lembrando-se do que fora, deixou {link:hearthglen}Amparo{/link} para encontrá-lo. A Cruzada o caçou na estrada, e o Grão-inquisidor Isillien o matou diante do pai. Em seu luto, Tirion declarou que a ordem a que servira não estava morta. Nomeou-se Grão-senhor de um novo Punho de Prata, renascido do antigo.]=],
		},
	},
	mentions = {
		{ text = "Redemption" },
		{ text = "Of Forgotten Memories" },
		{ text = "Of Lost Honor" },
		{ text = "Do Amor e da Família" },
		{ text = "In Dreams" },
	},
	bonds = {
		{ id = "eitrigg", name = "Eitrigg", note = "o orc que ele poupou" },
		{ id = "uther-the-lightbringer", name = "Uther the Lightbringer", note = "um irmão do Punho de Prata" },
		{ id = "alonsus-faol", name = "Alonsus Faol", note = "seu mestre na Luz" },
		{ id = "turalyon", name = "Turalyon", note = "um irmão do Punho de Prata" },
	},
})

Translate("ptBR", "garona", {
	title = "Garona",
	subtitle = "A Meio-orc",
	allegiance = "Desconhecida (antes o Conselho das Sombras)",
	sections = {
		{
			title = "Resumo",
			text = [=[Garona era uma meio-{link:orcs}orc{/link} de sangue misto, espiã e enviada da {link:horde}Horda{/link} na {link:first-war}Primeira Guerra{/link}. O bruxo {link:gul-dan}Gul'dan{/link} a enviou à torre de {link:medivh}Medivh{/link}. Ali ela fez amizade com o jovem mago {link:khadgar}Khadgar{/link} e passou a servir ao Rei {link:llane-wrynn}Llane Wrynn{/link} de {link:stormwind-city}Ventobravo{/link}. Também o assassinou.]=],
		},
		{
			title = "Importância",
			text = [=[Garona ajudou a levar a {link:stormwind-city}Ventobravo{/link} a verdade da traição de {link:medivh}Medivh{/link}, e desferiu o golpe que acabou com seu rei. Os dois feitos foram dela, e nenhum foi inteiramente seu.]=],
		},
		{
			title = "Enviada e Espiã",
			text = [=[Garona era desprezada entre os orcs por seu sangue misto, e aprendeu cedo a sobreviver pela astúcia. O {link:shadow-council}Conselho das Sombras{/link} de {link:gul-dan}Gul'dan{/link} fez uso dela. Ela veio a {link:karazhan}Karazhan{/link} como enviada da {link:horde}Horda{/link} ao Guardião. Ali ela e {link:khadgar}Khadgar{/link} descobriram que o próprio {link:medivh}Medivh{/link} trouxera os orcs a {link:azeroth}Azeroth{/link}. Esteve com Khadgar e {link:anduin-lothar}Anduin Lothar{/link} quando o Guardião foi morto. Depois entrou a serviço de {link:stormwind-city}Ventobravo{/link} e tornou-se conselheira de confiança do rei.]=],
		},
		{
			title = "Feitos",
			text = [=[• Serviu como enviada da {link:horde}Horda{/link} a {link:medivh}Medivh{/link} em {link:karazhan}Karazhan{/link}.
• Ajudou {link:khadgar}Khadgar{/link} a descobrir a traição de Medivh.
• Esteve presente na morte do Guardião.
• Matou o {link:llane-wrynn}Rei Llane{/link} Wrynn em seu próprio castelo.]=],
		},
		{
			title = "Destino",
			text = [=[A mente de Garona não lhe pertencia. Os bruxos do {link:shadow-council}Conselho das Sombras{/link} tinham um poder oculto sobre sua vontade. Quando {link:orgrim-doomhammer}Orgrim Doomhammer{/link} sitiou {link:stormwind-city}Ventobravo{/link} pela última vez, ela matou {link:llane-wrynn}Llane{/link} em seus aposentos, e o jovem príncipe {link:varian-wrynn}Varian Wrynn{/link} viu tudo. Então fugiu. Ninguém nos reinos sabe para onde foi.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Para onde Garona foi desde a queda de {link:stormwind-city}Ventobravo{/link}, e se ainda vive, as crônicas não dizem.]=],
		},
	},
	bonds = {
		{ id = "llane-wrynn", name = "Llane Wrynn", note = "seu rei, e sua vítima" },
		{ id = "khadgar", name = "Khadgar", note = "seu amigo em Karazhan" },
		{ id = "medivh", name = "Medivh", note = "o Guardião junto a quem ela serviu como enviada" },
		{ id = "gul-dan", name = "Gul'dan", note = "seu mestre" },
	},
})

Translate("ptBR", "alexstrasza", {
	title = "Alexstrasza",
	subtitle = "Rainha dos Dragões Vermelhos",
	allegiance = "Revoada Dragônica Vermelha",
	aliases = { "Alexstrasza", "a Mantenedora da Vida" },
	sections = {
		{
			title = "Resumo",
			text = [=[Alexstrasza é o Aspecto da Revoada {link:the-drag}Drag{/link}ônica Vermelha, a Rainha dos Dragões, guardiã da vida. Nos dias antigos, recebeu dos criadores do mundo poder sobre todos os seres vivos. Vigia {link:azeroth}Azeroth{/link} desde antes de os elfos construírem suas primeiras cidades. Nos anos da {link:second-war}Segunda Guerra{/link}, foi prisioneira dos orcs, e seus filhos foram transformados em armas de guerra.]=],
		},
		{
			title = "Importância",
			text = [=[Nenhuma raça mortal sofreu mais com a traição de {link:deathwing}Asa da Morte{/link} do que os dragões vermelhos. Seu cativeiro em {link:grim-batol}Grim Batol{/link} deu à {link:horde}Horda{/link} os seus dragões, e ainda é a causa do ódio entre a revoada vermelha e os orcs do {link:dragonmaw-clan}clã Presa do Dragão{/link}.]=],
		},
		{
			title = "Os Aspectos",
			text = [=[Nos dias antigos, cinco grandes dragões foram escolhidos para guardar o mundo. Alexstrasza, a maior deles, foi feita guardiã de toda a vida. {link:deathwing}Neltharion{/link}, o Guardião da Terra, era seu companheiro Aspecto. Na {link:war-of-the-ancients}Guerra dos Antigos{/link}, ele convenceu os Aspectos a dar parte de seu poder a seu grande disco de ouro, a Alma do {link:the-drag}Drag{/link}ão, e depois voltou-o contra eles. Os dragões foram dispersos, e a revoada vermelha sofreu terrivelmente. Alexstrasza nunca esqueceu.]=],
		},
		{
			title = "Grim Batol",
			text = [=[Na {link:second-war}Segunda Guerra{/link}, a Alma do {link:the-drag}Drag{/link}ão caiu nas mãos dos {link:dragonmaw-clan}orcs Presa do Dragão{/link}. Com seu poder, capturaram Alexstrasza e a prenderam sob a montanha de {link:grim-batol}Grim Batol{/link}, no {link:wetlands}Pantanal{/link}. Tomavam seus ovos assim que eram postos e criavam seus filhotes como montarias de guerra. Os dragões vermelhos voaram pela {link:horde}Horda{/link} contra a {link:alliance}Aliança{/link}, queimando as florestas de {link:quel-thalas}Quel'Thalas{/link} e as cidades do norte.]=],
		},
		{
			title = "Feitos",
			text = [=[• Foi escolhida como o Aspecto da vida nos dias antigos.
• Foi traída por {link:deathwing}Neltharion{/link} na {link:war-of-the-ancients}Guerra dos Antigos{/link}.
• Foi mantida cativa pelos {link:dragonmaw-clan}Presa do Dragão{/link} em {link:grim-batol}Grim Batol{/link}.
• Foi libertada e viu a Alma do {link:the-drag}Drag{/link}ão ser destruída.]=],
		},
		{
			title = "Os Dias de Hoje",
			text = [=[Muito depois da guerra, os {link:dragonmaw-clan}Presa do Dragão{/link} ainda mantinham a rainha. {link:deathwing}Asa da Morte{/link} veio a {link:grim-batol}Grim Batol{/link} buscar seus ovos, pretendendo tomar os filhos dela para si. Um pequeno grupo de heróis e dragões libertou Alexstrasza. A Alma do {link:the-drag}Drag{/link}ão foi destruída, e o poder dela voltou. Os dragões vermelhos se voltaram contra seus captores e rechaçaram Asa da Morte. Os Presa do Dragão ainda se agarram ao {link:wetlands}Pantanal{/link}, e os dragões vermelhos ainda os caçam. Onde a própria Rainha dos Dragões habita agora, poucos mortais sabem.]=],
		},
		{
			title = "Não Registrado",
			text = [=[As crônicas dos reinos pouco dizem de para onde a Rainha dos {link:the-drag}Drag{/link}ões foi desde sua libertação.]=],
		},
	},
	bonds = {
		{ id = "deathwing", name = "Asa da Morte", note = "seu companheiro Aspecto, e seu traidor" },
		{ id = "queen-azshara", name = "Rainha Azshara", note = "em cuja guerra os Aspectos foram traídos" },
	},
})

Translate("ptBR", "cenarius", {
	title = "Cenarius",
	subtitle = "Senhor da Floresta",
	allegiance = "As florestas de Kalimdor · Círculo Cenariano",
	sections = {
		{
			title = "Resumo",
			text = [=[Cenarius foi um semideus da natureza selvagem, senhor das florestas de {link:kalimdor}Kalimdor{/link}. Os {link:night-elves}elfos noturnos{/link} o tinham como filho de sua deusa da lua, Eluna. Foi o mestre de {link:malfurion-stormrage}Malfurion Stormrage{/link} e o pai das artes druídicas entre os mortais. Caiu na {link:third-war}Terceira Guerra{/link}, morto por {link:grom-hellscream}Grom Hellscream{/link} nos bosques do {link:ashenvale}Vale Gris{/link}.]=],
		},
		{
			title = "Importância",
			text = [=[Todo druida que anda pelo mundo percorre um caminho que Cenarius abriu. O {link:cenarion-circle}Círculo Cenariano{/link}, que reúne druidas elfos noturnos e {link:tauren}taurens{/link}, leva o seu nome. Sua morte foi uma ferida nas florestas de {link:kalimdor}Kalimdor{/link}, e os elfos noturnos não a perdoaram.]=],
		},
		{
			title = "O Primeiro Druida",
			text = [=[Na era anterior à {link:war-of-the-ancients}Guerra dos Antigos{/link}, Cenarius habitava os bosques do {link:mount-hyjal}Monte Hyjal{/link}. Tomou o jovem {link:malfurion-stormrage}Malfurion{/link} como aluno e ensinou-o a moldar os poderes da natureza. Quando a {link:burning-legion}Legião Ardente{/link} veio pelo {link:well-of-eternity}Poço da Eternidade{/link}, Cenarius levou os antigos espíritos da floresta à batalha ao lado dos elfos noturnos. Depois da {link:great-sundering}Grande Cisão{/link}, os druidas da ordem de Malfurion adotaram seus ensinamentos e os guardaram por dez mil anos. Seu nome viveu na Trompa de Cenarius, que Malfurion um dia soaria ao pé da Árvore do Mundo.]=],
		},
		{
			title = "Seus Filhos",
			text = [=[Cenarius teve muitos filhos. Dizem que as dríades e os guardiões do bosque são seus. Seu filho Zaetar foi o pai dos primeiros centauros, uma raça que hoje pouco lembra dele além de sua ira. Seu filho {link:keeper-remulos}Remulos{/link} guarda a clareira sagrada da {link:moonglade}Clareira da Lua{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ensinou a {link:malfurion-stormrage}Malfurion{/link} e aos primeiros druidas os caminhos da natureza.
• Liderou os espíritos da floresta na {link:war-of-the-ancients}Guerra dos Antigos{/link}.
• Vigiou as florestas de {link:kalimdor}Kalimdor{/link} por dez mil anos.
• Combateu os orcs que vieram cortar as árvores do {link:ashenvale}Vale Gris{/link}.
• A trompa que leva seu nome convocou os espíritos dos antigos contra {link:archimonde}Archimonde{/link} na {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Na {link:third-war}Terceira Guerra{/link}, os orcs do clã Brado Guerreiro vieram ao {link:ashenvale}Vale Gris{/link} cortar madeira. Os elfos noturnos os combateram, e Cenarius veio defender sua floresta. Os orcs não conseguiram resistir a ele. Em seu desespero, {link:grom-hellscream}Grom Hellscream{/link} e seus guerreiros beberam de uma fonte conspurcada pelo sangue de {link:mannoroth}Mannoroth{/link}, e a velha fúria os tomou. Naquela fúria mataram o semideus. Cenarius está morto. Seus druidas ainda o honram, e seus filhos ainda guardam seus bosques.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Se algum poder de Cenarius sobreviveu à sua morte, as crônicas não dizem.]=],
		},
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "seu aluno" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "seu matador" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "irmão de seu aluno" },
		{ id = "mannoroth", name = "Mannoroth", note = "cujo sangue enlouqueceu seus matadores" },
	},
})

Translate("ptBR", "kil-jaeden", {
	title = "Kil'jaeden",
	subtitle = "O Enganador",
	allegiance = "Legião Ardente",
	aliases = { "Kil'jaeden", "o Enganador" },
	sections = {
		{
			title = "Resumo",
			text = [=[Kil'jaeden, o Enganador, é um dos grandes senhores da {link:burning-legion}Legião Ardente{/link}, sujeito apenas à vontade de {link:sargeras}Sargeras{/link}. Foi outrora um líder dos eredar com {link:archimonde}Archimonde{/link}, e aceitou a oferta do titã sombrio como Archimonde. É um mestre da mentira. Foi Kil'jaeden quem corrompeu os orcs de {red:draenor}Draenor{/red}, e foi ele quem criou o {red:lich-king}Lich Rei{/red}.]=],
		},
		{
			title = "Importância",
			text = [=[Poucas das calamidades da última geração não têm a mão do Enganador. Por meio de {link:ner-zhul}Ner'zhul{/link} e de {link:gul-dan}Gul'dan{/link}, transformou os orcs numa arma. Por meio do Lich Rei, soltou o {link:scourge}Flagelo{/link} sobre {link:lordaeron}Lordaeron{/link}. Ao contrário de {link:archimonde}Archimonde{/link}, nunca foi derrotado.]=],
		},
		{
			title = "Os Eredar",
			text = [=[Há muito tempo, os eredar eram governados por três líderes: Kil'jaeden, {link:archimonde}Archimonde{/link} e Velen. {link:sargeras}Sargeras{/link} veio a eles com promessas de conhecimento e poder. Kil'jaeden e Archimonde aceitaram, e eles e seu povo foram deformados em demônios. Velen recusou e fugiu com seus seguidores. Kil'jaeden o odiou por isso, e jurou caçar o povo de Velen aonde quer que fosse.]=],
		},
		{
			title = "Os Orcs",
			text = [=[O povo de Velen, os draenei, chegou por fim a Draenor, onde viviam os orcs. Kil'jaeden os encontrou ali. Foi ao velho xamã {link:ner-zhul}Ner'zhul{/link} disfarçado de espírito dos ancestrais e disse-lhe que os draenei tramavam contra seu povo. Quando Ner'zhul começou a duvidar dele, o Enganador voltou-se para seu aprendiz, {link:gul-dan}Gul'dan{/link}, e ensinou-lhe as artes da {link:fel-magic}magia vil{/link}. Por meio de Gul'dan, deu aos orcs o sangue de {link:mannoroth}Mannoroth{/link}, prendeu-os à Legião e os lançou contra os draenei.]=],
		},
		{
			title = "Feitos",
			text = [=[• Aceitou a oferta de {link:sargeras}Sargeras{/link} e tornou-se um senhor da Legião.
• Enganou {link:ner-zhul}Ner'zhul{/link} e voltou os orcs contra os draenei.
• Ensinou a {link:gul-dan}Gul'dan{/link} as artes da magia vil.
• Transformou Ner'zhul no Lich Rei.
• Enviou o Lich Rei para preparar {link:azeroth}Azeroth{/link} para a Legião.]=],
		},
		{
			title = "O Lich Rei",
			text = [=[Quando {link:ner-zhul}Ner'zhul{/link} fugiu da ruína de Draenor, Kil'jaeden o esperava. Arrancou o corpo do xamã e prendeu seu espírito numa armadura e num elmo. Selou-o no gelo e o lançou sobre {red:northrend}Nortúndria{/red}, ordenando-lhe espalhar uma peste que enfraqueceria o mundo antes da chegada da Legião. O Lich Rei assim fez. Quando {link:archimonde}Archimonde{/link} caiu no {link:mount-hyjal}Monte Hyjal{/link}, o Enganador soube que seu servo começara a se soltar das correntes.]=],
		},
		{
			title = "Destino",
			text = [=[Kil'jaeden não pôs os pés em {link:azeroth}Azeroth{/link}. Depois da {link:third-war}Terceira Guerra{/link}, tentou fazer com que outros destruíssem o Lich Rei. O Lich Rei perdura, e o Enganador ainda observa de além do mundo.]=],
		},
		{
			title = "Não Registrado",
			text = [=[As crônicas não dizem onde Kil'jaeden habita, nem o que planeja agora.]=],
		},
	},
	bonds = {
		{ id = "archimonde", name = "Archimonde", note = "seu companheiro senhor da Legião" },
		{ id = "sargeras", name = "Sargeras", note = "seu mestre" },
		{ id = "ner-zhul", name = "Ner'zhul", note = "o xamã que ele enganou e transformou no Lich Rei" },
		{ id = "gul-dan", name = "Gul'dan", note = "seu servo entre os orcs" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "a quem enviou contra o Lich Rei" },
	},
})

Translate("ptBR", "sargeras", {
	title = "Sargeras",
	subtitle = "Senhor da Legião Ardente",
	allegiance = "Legião Ardente",
	aliases = { "O Titã Sombrio" },
	sections = {
		{
			title = "Resumo",
			text = [=[Sargeras é o senhor da {link:burning-legion}Legião Ardente{/link}, um titã caído que busca desfazer toda a criação. Foi outrora o maior campeão dos titãs, os criadores de mundos, e combateu os demônios do Espiralume por eras incontáveis. Com o tempo, perdeu a esperança em sua obra. Libertou os demônios que aprisionara, reuniu-os numa hoste e a voltou contra cada mundo que os titãs haviam moldado.]=],
		},
		{
			title = "Importância",
			text = [=[Cada guerra que a Legião travou em {link:azeroth}Azeroth{/link} foi travada em nome de Sargeras. Ele alcançou o mundo três vezes: por meio da {link:queen-azshara}Rainha Azshara{/link}, por meio de {link:aegwynn}Aegwynn{/link} e de seu filho {link:medivh}Medivh{/link}, e por meio dos orcs que prendeu à sua vontade. Sua sombra está por trás da {link:war-of-the-ancients}Guerra dos Antigos{/link}, da {link:first-war}Primeira Guerra{/link} e da {link:third-war}Terceira Guerra{/link}.]=],
		},
		{
			title = "O Titã Caído",
			text = [=[As histórias dizem que Sargeras caçou demônios através da Grande Escuridão por mais tempo do que qualquer mortal pode calcular. O que viu ali transformou seu coração. Passou a acreditar que a própria criação era falha e não podia ser reparada. Libertou os demônios que capturara, corrompeu os eredar por meio de {link:archimonde}Archimonde{/link} e de {link:kil-jaeden}Kil'jaeden{/link}, e assim nasceu a Legião.]=],
		},
		{
			title = "Azeroth",
			text = [=[Dez mil anos atrás, a {link:queen-azshara}Rainha Azshara{/link} e seus Bem-nascidos atraíram seu olhar com o poder do {link:well-of-eternity}Poço da Eternidade{/link}. Sargeras enviou sua Legião pelo portal deles e tentou entrar ele mesmo no mundo. O Poço foi destruído antes que ele pudesse. Eras depois, apareceu diante da Guardiã {link:aegwynn}Aegwynn{/link} numa grande tempestade em {red:northrend}Nortúndria{/red}. Ela matou seu avatar e selou o corpo numa tumba sob o mar. O espírito dele escondeu-se dentro dela e passou para seu filho ainda não nascido. Por meio de {link:medivh}Medivh{/link}, o titã sombrio abriu o {link:dark-portal}Portal Negro{/link} e trouxe os orcs a {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Foi outrora o campeão dos titãs.
• Libertou os demônios que aprisionara e fundou a {link:burning-legion}Legião Ardente{/link}.
• Corrompeu os eredar por meio de {link:archimonde}Archimonde{/link} e {link:kil-jaeden}Kil'jaeden{/link}.
• Sussurrou a {link:azshara}Azshara{/link} e quase entrou no mundo.
• Escondeu-se dentro de {link:aegwynn}Aegwynn{/link} e de {link:medivh}Medivh{/link}, e por meio dele abriu o {link:dark-portal}Portal Negro{/link}.]=],
		},
		{
			title = "Destino",
			text = [=[Sargeras nunca andou em {link:azeroth}Azeroth{/link} em sua verdadeira forma. Seu avatar jaz em sua tumba sob o mar, que o bruxo {link:gul-dan}Gul'dan{/link} ergueu e onde entrou para a própria morte. Quando {link:medivh}Medivh{/link} foi morto, o domínio do titã sombrio sobre o mundo foi quebrado. Mas a Legião que ele lidera permanece, e seus senhores não abandonaram a fome por este mundo.]=],
		},
		{
			title = "Não Registrado",
			text = [=[O que foi feito do espírito de Sargeras quando {link:medivh}Medivh{/link} morreu, as crônicas dos reinos não sabem dizer.]=],
		},
	},
	bonds = {
		{ id = "archimonde", name = "Archimonde", note = "seu tenente" },
		{ id = "kil-jaeden", name = "Kil'jaeden", note = "seu tenente" },
		{ id = "aegwynn", name = "Aegwynn", note = "matou seu avatar" },
		{ id = "medivh", name = "Medivh", note = "seu receptáculo" },
		{ id = "queen-azshara", name = "Rainha Azshara", note = "sua serva" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "recebeu seu presente" },
	},
})

Translate("ptBR", "mannoroth", {
	title = "Mannoroth",
	subtitle = "O Destruidor",
	allegiance = "Legião Ardente",
	aliases = { "Mannoroth", "o Destruidor" },
	sections = {
		{
			title = "Resumo",
